(window.GIM_TS=window.GIM_TS||{})["Bava Batra.11"]={"from":264,"a":[["\u0003אם לאו\u0004 \u0005[לא],\u0006 הרי זה משום שנכסים אלו שלי הם לכל ענין, ולכן גם \u0003אי\u0004 (אין) \u0003אתה יכול להוציא מה שהחזרתי\u0004 לבנים. \u0003אמר\u0004 שמאי: \u0003הטיח עלי בן עוזיאל! הטיח עלי בן עוזיאל!\u0004 שאמר לי דבר שאיני יכול להשיב כנגדו.","ושואלים: ושמאי \u0003מעיקרא מאי\u0004 \u0005[מתחילה מה]\u0006 \u0003סבר\u0004 שהתרעם על יונתן בן עוזיאל? ומשיבים: \u0003משום מעשה\u0004 שהיה ב\u0003בית חורון,\u0004 ממנו משמע לכאורה שמתנה כזו איננה חלה.","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מעשה בבית חורון באחד שהיה אביו מודר הימנו\u0004 (ממנו) \u0003הנאה,\u0004 שנדר אביו שלא יהנה ממנו, \u0003והיה\u0004 אותו בן \u0003משיא\u0004 את \u0003בנו,\u0004 ורצה להזמין את אביו לחתונה, \u0003ואמר לחבירו: הרי\u0004 ה\u0003חצר\u0004 בה נערכת החתונה \u0003ו\u0004כן ה\u0003סעודה נתונין לך במתנה, ואינן לפניך אלא כדי שיבא אבא ויאכל עמנו בסעודה.\u0004","\u0003אמר לו\u0004 אותו חבר: \u0003אם שלי הן\u0004 — \u0003הרי הן מוקדשין לשמים! אמר לו\u0004 הנותן בתרעומת: \u0003לא נתתי לך את שלי שתקדישם לשמים! אמר לו: לא נתת לי את שלך אלא שתהא אתה ואביך אוכלין ושותין ומרצין זה לזה, ויהא עון\u0004 של חילול הנדר \u0003תלוי בראשו\u0004 של זה שאיפשר את הדבר. כלומר בראשי!","ועל כך \u0003אמרו חכמים: כל מתנה שאינה\u0004 נתונה לחלוטין למקבל, עד \u0003שאם הקדישה\u0004 תהא \u0003מוקדשת\u0004 — \u0003אינה מתנה.\u0004 ומתחילה סבר שמאי שהמתנה שקיבל יונתן בן עוזיאל אף היא לא היתה מתנה גמורה, אלא רק כדי שלא יינתנו הנכסים לבניו של אותו אדם. ואולם כיון ששמע שהקדיש חלק לשמים, משמע שהיתה זו מתנה גמורה, ויכול היה לעשות בה מה שירצה.","אגב הזכרת שמו של יונתן בן עוזיאל מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמונים תלמידים היו לו להלל הזקן, שלשים מהן ראוים שתשרה עליהן שכינה כמשה רבינו, שלשים מהן ראוים שתעמוד להן חמה כיהושע בן נון, עשרים בינוניים\u0004 בין אלה לאלה. \u0003גדול שבכולן\u0004 בין כל התלמידים היה \u0003יונתן בן עוזיאל, קטן שבכולן\u0004 היה \u0003רבן יוחנן בן זכאי.\u0004","\u0003אמרו עליו על רבן יוחנן בן זכאי,\u0004 \u0003שלא הניח\u0004 מללמוד ולדעת \u0003מקרא ומשנה, תלמוד, הלכות ואגדות, דקדוקי תורה ודקדוקי סופרים\u0004 פרטים של דברי חכמים, ודרשות הנלמדות ב\u0003קלין וחמורין\u0004 (בדרך קל וחומר), \u0003ו\u0004כן \u0003גזרות שוות, ותקופות,\u0004 כלומר, חשבונות של לוח השנה, \u0003וגמטריאות, ומשלות כובסים\u0004 שהיו אומרים משלים שיש בהם חכמה, \u0003ומשלות שועלים,\u0004 שמשתמשים בחיות כמשל, \u0003שיחת שדים, ושיחת דקלים, ושיחת מלאכי השרת, ו\u0004למד וידע גם \u0003דבר גדול ו\u0004גם \u0003דבר קטן.\u0004","ומסבירים: \u0003\"דבר גדול\"\u0004 הוא \u0003מעשה מרכבה\u0004 שהוא לימוד סודות ההנהגה האלוקית, שהם דבר הגדול, העומד ברומו של עולם, \u0003ו\"דבר קטן\"\u0004 בהשוואה לזה, הן \u0003הויות\u0004 (הדיונים והמחלוקות) של \u0003אביי ורבא,\u0004 וממשיכה הברייתא: ומה שנאמר על ר' יוחנן בן זכאי יש בו \u0003לקיים מה שנאמר: \"להנחיל אוהבי יש ואצרתיהם אמלא\"\u0004 (משלי ח, כא), שהיה ממולא בכל אוצרות החכמה.","ומוסיפים: \u0003וכי מאחר\u0004 ש\u0003קטן שבכולם\u0004 של תלמידי הלל הזקן, רבן יוחנן בן זכאי \u0003כן\u0004 היתה גדולתו, \u0003גדול שבכולם,\u0004 כלומר, יונתן בן עוזיאל, \u0003על אחת כמה וכמה.\u0004 ומפרשים עוד בגדולתו: \u0003אמרו עליו על יונתן בן עוזיאל, בשעה שיושב ועוסק בתורה\u0004 — \u0003כל עוף שפורח עליו נשרף\u0004 מחמת גודל קדושתו.","\u0003האומר \"זה בני\"\u0004 — הרי הוא \u0003נאמן,\u0004 \u0003\"זה אחי\"\u0004 — \u0003אינו נאמן\u0004 לחייב את אחיו האחרים לתת לאח זה חלק בירושה מחלקם. ואולם כיון שהוא אמר שאחיו הוא, הריהו נאמן לגבי עצמו \u0003ויטול עמו בחלקו\u0004 שלו בירושת אביהם.","אם \u0003מת\u0004 אותו אח מסופק — \u0003יחזרו נכסים\u0004 שירש מאביהם \u0003למקומן\u0004 לחלקו של האח שמעיד עליו, ושנתן לו מחלקו.","ואולם אם \u0003נפלו לו\u0004 בירושה לאח שהעיד עליו \u0003נכסים ממקום אחר\u0004 (לא מאביהם), ומת האח המסופק — \u0003יירשו\u0004 כל \u0003אחיו עמו\u0004 עם האח שהעיד עליו, שהרי לטענתו גם הם יורשי אותו אח.","שנינו במשנה שהאומר \u0003\"זה בני\" נאמן.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזה ענין נאמרה \u0005הלכה\u0006 זו\u0005]?\u0006 \u0003אמר רב יהודה אמר שמואל: ליורשו,\u0004 כלומר, שאותו בן יורש אותו. \u0003ו\u0004כן \u0003לפטור את אשתו מן היבום.\u0004 שכיון שהוא אומר שזה בנו, ממילא אין אשתו צריכה להתייבם לאחר מותו, שהרי יש לו בן."],["ותוהים: \u0003ליורשו, פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שהאב נאמן בכך, שהרי אם היה רוצה היה יכול לתת לו נכסיו אלה במתנה, ואין צורך להשמיענו זאת! ומשיבים: \u0003לפטור את אשתו מן היבום אצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 שנאמן האב על כך, למרות שאין הדבר בידו.","ושואלים: אף זאת לא היה צריך להשמיענו, שכן \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שאמר בשעת מיתתו \"יש לי בנים\"\u0004 — הרי זה \u0003נאמן,\u0004 ואשתו פטורה מן הייבום, אם אמר: \u0003\"יש לי אחים\",\u0004 ולכן צריכה אשתו ייבום — \u0003אינו נאמן!\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 באותה משנה, מדובר ש\u0003לא מוחזק לן\u0004 \u0005[לנו]\u0006 שיש לו \u0003אח\u0004 הזוקק את אשתו ליבום, והרי אשתו בחזקת פטורה מן הייבום, וכשהוא אומר שיש לו בן אינו אלא מקיים את חזקת אשתו, \u0003הכא אף על גב\u0004 \u0005[כאן\u0006 נוסף חידוש, ש\u0005אף על פי]\u0006 ש\u0003מוחזק ליה\u0004 \u0005[לו]\u0006 \u0003באח,\u0004 מכל מקום הוא נאמן לומר \"זה בני\", ולפטור את אשתו מן הצורך בייבום.","ודנים בחידוש זה של משנתנו, \u0003אמר רב יוסף אמר רב יהודה אמר שמואל: מפני מה אמרו\u0004 שהאומר \u0003\"זה בני\"\u0004 — \u0003נאמן?\u0004 — \u0003הואיל ו\u0004נאמן הוא לפוטרה מן הייבום בדרך אחרת, שהרי \u0003בעל שאמר \"גרשתי את אשתי\"\u0004 — \u0003נאמן\u0004 בכך, וגרושה אינה חייבת בייבום.","לאחר שחלה ושכח מקצת תלמודו, \u0003אמר רב יוסף\u0004 בתמיהה על הדברים שאמר בשם רבו: \u0003מריה\u0004 \u0005[אדוניו]\u0006 של \u0003אברהם,\u0004 בלשון תמיהה ושבועה, \u0003תלי תניא בדלא תניא\u0004 \u0005[\u0006הרי זה \u0005תולה\u0006 מנמק הלכה \u0005שנויה\u0006 במשנה, \u0005ב\u0006אמצעות הלכה \u0005שאינה שנויה],\u0006 שהרי נאמנותו של האב האומר \"זה בני\" נשנית במשנה, ואילו נאמנותו של בעל האומר \"גרשתי את אשתי\" אינה אמורה במשנה, אלא בשם אמוראים!","\u0003אלא אי אתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 \u0003אמר רב יהודה אמר שמואל: מפני מה אמרו \"זה בני\" נאמן\u0004 לפטור את אשתו מן הייבום? \u0003הואיל ובידו לגרשה\u0004 ובכך לפוטרה מן הייבום.","ועל כך הוסיף ו\u0003אמר רב יוסף, השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"הואיל\u0004 ובידו לגרשה \u0003\",\u0004 וסומכים על כך כיסוד לנאמנותו של בעל, \u0003בעל שאמר \"גרשתי את אשתי\"\u0004 — אף הוא \u0003נאמן, הואיל ובידו לגרשה\u0004 בכל עת.","ומסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: בעל שאמר \"גרשתי את אשתי\"\u0004 — \u0003אינו נאמן. מנפח\u0004 \u0005[היה מנפנף]\u0006 \u0003רב ששת בידיה\u0004 \u0005[בידו]\u0006 בתנועה של ביטול כאומר: בדברי ר' יוחנן אלו \u0003אזל ליה\u0004 \u0005[הלך,\u0006 התבטל \u0005לו]\u0006 הנימוק \u0003\"הואיל\u0004 ובידו לגרשה \u0003\"\u0004של \u0003רב יוסף.\u0004","ושואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 האם כך אמנם אמר ר' יוחנן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר\u0004 \u0003ר' חייא בר אבין אמר\u0004 \u0003ר' יוחנן: בעל שאמר \"גרשתי את אשתי\"\u0004 — \u0003נאמן!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן למפרע,\u0004 לגבי דבר שהיה אינו נאמן, כגון שמעיד שגירשה בתאריך מסויים, אם מתברר שזנתה לאחר אותו תאריך — ולפי דבריו אלה פנויה היתה — אין מאמינים לו לפוטרה מן העונש, שהרי אין בידו לגרשה למפרע.","\u0003כאן להבא,\u0004 כגון שאומר \"גירשתיה היום\". שלגבי מה שקורה מאותו זמן והלאה הריהו נאמן, ואם ימות — אינה צריכה ייבום, ואם תזנה — דינה כפנויה, כיון שבידו לגרשה בשעה שאמר.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: אם \u0003אמר\u0004 שגירש את אשתו \u0003למפרע,\u0004 כלומר, בתאריך מסויים, \u0003מהו להימוניה\u0004 \u0005[להאמין לו\u0006 לקבל את דבריו\u0005]\u0006 \u0003להבא\u0004 ולהחזיקה כגרושה מכאן ואילך, אף שאין מאמינים לו לגבי העבר?","ותמצית השאלה היא: \u0003מי פלגינן דבורא\u0004 \u0005[האם אנו מחלקים\u0006 את \u0005הדיבור]\u0006 ואומרים שאף שעל הזמן שהעיד עליו אינו נאמן, אבל על דבריו שגירשה — הריהו נאמן מכאן ולהבא, שהרי בידו לגרשה עכשיו, \u0003או לא פלגינן דבורא\u0004 \u0005[אין אנו מחלקים\u0006 את \u0005הדיבור],\u0006 וכיון שאמרנו שאינו נאמן לומר שגירשה אז, נמצא שאיננה גרושה אף מכאן ולהבא? \u0003רב מארי ורב זביד\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: פלגינן\u0004 \u0005[חולקים אנו]\u0006 את הדיבור, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא פלגינן\u0004 \u0005[אין אנו חולקים]\u0006 את הדיבור.","ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שאמר \u0003רבא?\u0004 ש\u0003אמר רבא:\u0004 האומר \u0003\"איש פלוני בא על אשתי\"\u0004 — \u0003הוא ואחר\u0004 שראה את הדבר \u0003מצטרפין\u0004 לעדות כדי \u0003להורגו\u0004 בבית דין על פיהם, כמי שבא על אשת איש, ומדייקים: מצטרף הוא לעדות לאותו פלוני \u0003להורגו, ולא להורגה\u0004 שאין הורגים את האשה על פי עדות זאת, גם אם הם מעידים שזנתה מרצונה. וטעמו של דבר — משום שהבעל אינו נאמן להעיד על אשתו מפני קרבתו אליה. נמצא שבאותה עדות על אותו מעשה עצמו חולקים אנו את הדיבור, וסומכים על מה שהעיד שפלוני בא על אשת איש, למרות שלא ניתן לקבל את חלקה השני של העדות שהיתה זו אשתו!","ומשיבים: \u0003בתרי גופי פלגינן\u0004 \u0005[בשני גופים מחלקים אנו]\u0006 את הדיבור, וכיון שמדובר באותו פלוני ובאשה אפשר לחלק את העדות, ואולם \u0003בחד גופא לא פלגינן\u0004 \u0005[בגוף אחד,\u0006 כלומר, באשתו שנתגרשה, \u0005אין אנו מחלקים]\u0006 את הדיבור, לומר שחלק מן הדיבור (לגבי התאריך) יוחזק כשקר, והחלק האחר (לגבי הגירושין) עצמם ייחשב אמיתי."],["מסופר: \u0003ההוא דהוה קא שכיב\u0004 \u0005[\u0006אדם \u0005אחד שהיה חולה\u0006 ונטה למות\u0005],\u0006 וידוע היה שיש לו אחים ולא בנים, ומשום כך מוחזקת אשתו כמי שעומדת ליבום, \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אתתיה למאן\u0004 \u0005[אשתך למי]?\u0006 כלומר, מי יהיה בעלה? האם זקוקה היא לייבום, או שהיא מותרת להינשא לכל מי שהיא רוצה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003חזיא לכהנא רבה\u0004 \u0005[ראויה\u0006 היא \u0005לכהן גדול],\u0006 כלומר, אינה זקוקה ליבום, לפי שכבר גירשתיה, ולאו דווקא לכהן גדול, שהרי גרושה אסורה אפילו לכהן הדיוט, אלא כוונתו שכל אדם יכול להיות בעלה.","\u0003אמר רבא:\u0004 וכי \u0003מאי ניחוש\u0004 \u0005[מה נחשוש]\u0006 \u0003לה?\u0004 מדוע לא נאמין לו? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב חייא בר אבא אמר\u0004 \u0003ר' יוחנן: בעל שאמר \"גרשתי את אשתי\"\u0004 — \u0003נאמן\u0004 ופטורה מיבום! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003ר' יצחק בר יוסף\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: בעל שאמר \"גרשתי את אשתי\"\u0004 — \u0003אינו נאמן! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולאו מי לא שנינהו\u0004 \u0005[והאם לא תירצנו\u0006 כבר את הדבר\u0005]\u0006 ואמרנו: \u0003כאן למפרע וכאן להבא?\u0004","אמר לו אביי: \u0003ואשנויי ניקום ולסמוך\u0004 \u0005[ועל תירוצים נעמוד ונסמוך]\u0006 לפסוק הלכה? כלומר, אף שניתן הסבר מסויים לקושי זה, לא ברור כלל שהתירוץ הזה הוא תירוץ של אמת, ויש איפוא לחשוש לדברים שאמר בשמו רב יצחק בר יוסף. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נתן בר אמי: חוש לה\u0004 \u0005[תחשוש לכך]\u0006 שמא אכן יש מחלוקת בדבר זה, ואין אנו סומכים בשלימות על התירוצים.","ועוד מסופר: \u0003ההוא דהוה מוחזק לן דלית ליה אחי\u0004 \u0005[\u0006אדם \u0005אחד שהיה\u0006 \u0005מוחזק לנו שאין לו אחים],\u0006 \u0003ואמר בשעת מיתה דלית ליה אחי\u0004 \u0005[שאין לו אחים],\u0006 ולא היו לו בנים. והשאלה היתה האם ניתן להתיר לאשתו להינשא. \u0003אמר רב יוסף: מאי ליחוש לה\u0004 \u0005[מה נחשוש לכך]?\u0006 \u0003חדא\u0004 \u0005[אחת],\u0006 שהוא \u0003מוחזק לן\u0004 \u0005[לנו]\u0006 \u0003דלית ליה אחין\u0004 \u0005[שאין לו אחים].\u0006 \u0003ועוד, הא\u0004 \u0005[הרי]\u0006 הוא עצמו \u0003אמר בשעת מיתה דלית ליה\u0004 \u0005[שאין לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: הא אמרי דאיכא\u0004 \u0005[הרי אומרים\u0006 אנשים \u0005שיש]\u0006 \u0003עדים במדינת הים דידעי דאית ליה אחי\u0004 \u0005[שיודעים שיש לו אחים]!\u0006","ענה לו רב יוסף: \u0003השתא מיהת הא ליתנהו קמן\u0004 \u0005[עכשיו על כל פנים אינם מצויים לפנינו],\u0006 ואין אנו צריכים לחשוש לעדות מסופקת זו. והוסיף: \u0003לאו היינו\u0004 \u0005[האם אין זו]\u0006 כאותה הלכה שפסק \u0003ר' חנינא,\u0004 שהביאו לפניו שבויות שאמרו שלא נטמאו (והדין במקרה כזה הוא שהן נאמנות אם אין עדים שמעידים שנשבו), שאף שאמרו אנשים שיש עדים במקום אחר שנטמאו, \u0003אמר\u0004 \u0003ר' חנינא: עדים בצד אסתן\u0004 \u0005[צפון],\u0006 אי שם במקום אחר, \u0003ותאסר\u0004 משום כך?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אם הקלנו בשבויה\u0004 שיש צדדים רבים להקל בה, ובין השאר \u0003משום דמנוולא נפשה לגבי שבאי\u0004 \u0005[שמנוולת\u0006 את \u0005עצמה לפני השובה]\u0006 שמנסה ככל האפשר להיראות דוחה ומכוערת בעיניו, ולכן יש להניח שלא נטמאה, \u0003נקל באשת איש? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נתן בר אמי: חוש\u0004 \u0005[תחשוש]\u0006 \u0003לה\u0004 לטענה זו, ואל תעשה מעשה להתיר אשה זו עד שיתברר הדבר.","שנינו במשנה שהאומר \u0003\"זה אחי\"\u0004 — \u0003אינו נאמן\u0004 לחייב את שאר האחים, ויטול אותו אח ממנו חלק בירושה. ושואלים: \u0003ואידך מאי קאמרי\u0004 \u0005[ו\u0006האחים \u0005האחרים מה הם אומרים]?\u0006 \u0003אי קאמרי אחונא\u0004 \u0005[אם הם אומרים אחינו]\u0006 \u0003הוא,\u0004 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יטול עמו בחלקו\u0004 של אח זה \u0003ותו לא\u0004 \u0005[ולא עוד]?\u0006 הרי גם הם מודים בכך, ויתנו לו גם מחלקם! \u0003אלא\u0004 תפרש שמדובר \u0003דקא אמרי\u0004 \u0005[שהם אומרים]:\u0006 \u0003\"לאו\u0004 \u0005[לא]\u0006 \u0003אחינו הוא\".\u0004","ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]:\u0006 אם \u0003נפלו לו\u0004 לאותו ספק \u0003נכסים ממקום אחר\u0004 ומת — \u0003יירשו אחיו עמו\u0004 את נכסי אותו ספק. ואם מדובר שהם טוענים בוודאות שאין הוא אחיהם, מה זכותם לירש? \u0003הא אמרי ליה\u0004 \u0005[הרי אומרים\u0006 הם \u0005לו]:\u0006 \u0003\"לאו אחונא\u0004 \u0005[לא אחינו]\u0006 \u0003הוא\"!\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דקא אמרי\u0004 \u0005[שהם אומרים]:\u0006 \u0003\"אין אנו יודעין\",\u0004 ולכן אינם נותנים לו חלק — לפי שאין בידו ראיה. אבל יכולים הם לבוא ולתבוע מכח הודאת האח האחר.","\u0003אמר רבא: זאת אומרת\u0004 שהבא לחבירו וטוען \u0003\"מנה לי בידך\", והלה\u0004 הנתבע \u0003אומר \"איני יודע\"\u0004 — הרי הוא \u0003פטור,\u0004 שהרי האחים האחרים כשאומרים שאינם יודעים, אינם צריכים לתת מחלקם כלום.","\u0003אביי אמר:\u0004"],["\u0003לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך\u0004 שהאומר \"איני יודע\" מול תביעת \"מנה לי בידך\" — \u0003חייב, ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 שאין האחים חייבים לתת לספק מחלקם, משום שהאח שהכיר בו, \u0003כ\u0004טוען \u0003\"מנה לאחר בידך\" דמי\u0004 \u0005[נחשב],\u0006 ובמקרה כזה, שלא בעל הדבר עצמו הוא תובע — די בטענת \"איני יודע\" כדי לדחות את התביעה.","שנינו במשנה: \u0003מת\u0004 אותו ספק — \u0003יחזרו נכסים\u0004 שנתן לו אותו אח \u0003למקומן,\u0004 לאותו אח. ואולם אם נפלו נכסים ממקום אחר לידי האח הספק — יחלקו כל האחים בהם. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: שבח ששבחו\u0004 אותם \u0003נכסים\u0004 שנתן לו האח \u0003מאליהם, מהו\u0004 הדין? למי הם שייכים?","ומעירים: \u0003ב\u0004מקרה של \u0003שבח המגיע לכתפים,\u0004 שהפירות הבשילו לגמרי, ולא נותר אלא ליטול אותם מן השדה — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 \u0003דכי\u0004 \u0005[שכמו]\u0006 ש\u0003נפלו לו נכסים ממקום אחר דמי\u0004 \u0005[נחשב\u0006 הדבר\u0005],\u0006 וכל האחים מתחלקים בו, לפי שאינו נחשב כחלק מהקרקע שנתן לו. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה \u0003בשבח שאינו מגיע לכתפים,\u0004 שאינו נפרד מגוף הקרקע, \u0003כגון דיקלא ואלים\u0004 \u0005[דקל שנעשה עבה],\u0006 או \u0003ארעא ואסקא\u0004 \u0005[אדמה שהעלתה]\u0006 \u0003שרטון\u0004 והושבחה, אם כן \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם גם זה בכלל הקרקע, או כנכסים אחרים? לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003מי שמת ונמצאת דייתיקי\u0004 (שטר צוואת שכיב מרע) \u0003קשורה על יריכו\u0004 באופן שברור שהוא כתבו — \u0003הרי זו אינה כלום,\u0004 שהשטר כשלעצמו אינו מועיל, ועוד, שמא לאחר שכתב את השטר נמלך ולא רצה לתיתו. אבל אם עוד בחייו \u0003זיכה בה\u0004 (אותה) \u0003לאחר\u0004 שאמר לו: זכה בצוואה זו עבור פלוני, \u0003בין\u0004 שהיה אותו אדם אחר \u0003מן היורשין, בין שאינן מן היורשין\u0004 — \u0003דבריו קיימין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזה היא דייתיקי\u0004 שגובה בה המקבל לאחר מיתה? \u0003כל שכתוב בה: \"דא\u0004 \u0005[זו]\u0006 \u0003תהא למיקם\u0004 \u0005[לעמוד]\u0006 \u0003ולהיות\u0004 אחר מותי \u0003\",\u0004 שכך רצוני שייעשה. \u0003ואיזה היא\u0004 שטר \u0003מתנה\u0004 שאדם גובה בו? \u0003כל שכתוב בה: \"מהיום ולאחר מיתה\".\u0004","ותוהים: \u0003אלא,\u0004 האם תאמר שרק כשכתוב בנוסח \u0003\"מהיום ולאחר מיתה\" הוא דהויא\u0004 \u0005[שתהיה]\u0006 \u0003מתנה,\u0004 ואם אומר שתהיה \u0003\"מעכשיו\" לא הויא\u0004 \u0005[אינה]\u0006 \u0003מתנה? אמר אביי,\u0004 \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריכים להבין את הדברים: \u0003איזו היא מתנת בריא שהיא כמתנת שכיב מרע,\u0004 ש\u0003לא קני\u0004 \u0005[קונה]\u0006 אותה המקבל \u0003אלא לאחר מיתה? כל שכתוב בה: \"מהיום ולאחר מיתה\".\u0004 אבל אם כתוב בה \"מעכשיו\" — הרי קונה את המתנה מיד.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבה בר רב הונא באכסדרא דבי\u0004 \u0005[במרפסת של בית\u0006 מדרשו\u0005]\u0006 של \u0003רב, ויתיב וקאמר משמיה\u0004 \u0005[ויושב\u0006 היה \u0005ואומר משמו]\u0006 של \u0003ר' יוחנן: שכיב מרע שאמר \"כתבו ותנו מנה\u0004 מנכסי \u0003לפלוני\" ומת\u0004 — \u0003אין כותבין ונותנין.\u0004 והטעם: \u0003שמא לא גמר\u0004 בדעתו \u0003להקנותו\u0004 לאותו פלוני את מתנתו \u0003אלא בשטר, ו\u0004כיון שלא נכתב השטר בחייו שוב אי אפשר לכותבו לאחר מיתה, לפי ש\u0003אין שטר\u0004 מקנה \u0003לאחר מיתה.\u0004","וסיפר רבה בר רב הונא, שכשאמר ר' יוחנן הלכה זו \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אלעזר\u0004 לחכמים: \u0003איזדהרו\u0004 \u0005[היזהרו]\u0006 \u0003בה,\u0004 כלומר, הלכה זו נכונה היא, וצריך לחשוש לדבר זה. \u0003רב שיזבי אמר:\u0004 לא כך היה המעשה, אלא \u0003ר' אלעזר\u0004 הוא ש\u0003אמרה\u0004 להלכה זו, \u0003ואמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יוחנן\u0004 לתלמידיו: \u0003איזדהרו\u0004 \u0005[היזהרו]\u0006 \u0003בה.\u0004","\u0003אמר רב נחמן בר יצחק: כותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב שיזבי מסתברא\u0004 \u0005[מסתבר],\u0006 ומדוע? כי \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003ר' אלעזר אמרה\u0004 להלכה זו, \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 \u0003ר' יוחנן לאסהודי עליה\u0004 \u0005[להעיד עליו]\u0006 על \u0003ר' אלעזר,\u0004 ולחזק את דבריו שאכן כך הוא להלכה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003ר' יוחנן אמרה,\u0004 וכי \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 \u0003ר' אלעזר לאסהודי עליה\u0004 \u0005[להעיד עליו\u0006 על\u0005]\u0006 \u0003ר' יוחנן רביה\u0004 \u0005[רבו]\u0006 שדבריו נכונים?","\u0003ועוד, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במקום אחר ש\u0003ר' אלעזר אמרה\u0004 להלכה זו, ש\u0003שלח רבין משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אבהו: הוו\u0004 (היו) \u0003יודעים ששלח\u0004 \u0003ר' אלעזר לגולה משום\u0004 (בשם) \u0003רבינו\u0004 (רב): \u0003שכיב מרע שאמר \"כתבו ותנו מנה לפלוני\" ומת\u0004 — \u0003אין כותבין ונותנין, שמא לא גמר להקנותו אלא בשטר, ואין שטר לאחר מיתה, ור' יוחנן אמר: תיבדק,\u0004 כלומר, לגוף הדבר הדברים נכונים, אלא שצריך לבדוק מה בדיוק היה נוסח דבריו של המצווה.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003\"תיבדק\"\u0004 זה? ומשיבים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 שתי הלכות. הראשונה: \u0003דייתיקי מבטלת דייתיקי,\u0004 שטר צוואה מבטל שטר צוואה אחר שנכתב לפניו. ועוד אמר הלכה נוספת, שיש בה להסביר מהי אותה הבדיקה שהצריך ר' יוחנן: \u0003שכיב מרע שאמר \"כתבו ותנו מנה לפלוני\" ומת\u0004 — \u0003רואין,\u0004 כלומר, בודקים מה היתה כוונתו: \u0003אם כמיפה את כחו\u0004 אמר שיכתבו. שהתכוון לתת לו את המנה בלא קשר לכתיבה, אלא שאמר שגם יכתבו לו את הדבר — כדי ליפות את כוחו שיהא בידו גם מסמך כתוב — \u0003כותבין\u0004 גם לאחר מיתה, \u0003ואם לאו\u0004 \u0005[לא],\u0006 שהתכוון לומר שיקנה דווקא באופן זה של כתיבה — \u0003אין כותבין\u0004 ונותנים, שהרי אין כותבים שטר לאחר מיתה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אבא בר ממל\u0004 ממה ששנינו בברייתא: \u0003בריא שאמר \"כתבו ותנו מנה לפלוני\" ומת\u0004 — \u0003אין כותבין ונותנין,\u0004 ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה זה \u0003שכיב מרע\u0004 — \u0003כותבין ונותנין!\u0004 ואומרים: \u0003הוא מותיב לה, והוא מפרק לה\u0004 \u0005[הוא היה מקשה את\u0006 הקושיה \u0005הזו, והוא היה מתרץ אותה]:\u0006 שמדובר שם \u0003במיפה את כחו.\u0004","ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003מיפה את כחו?\u0004"],["\u0003אמר רב חסדא\u0004 בענין דומה: שאם כותב \u0003\"וקנינא מיניה\u0004 \u0003מוסיף על מתנתא דא\"\u0004 \u0005[וקנינו ממנו בנוסף למתנה זו],\u0006 הרי זה ייפוי כח לענין מתנת שכיב מרע שנכתב בה קנין. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין כתיבה, ייפוי כח הוא ש\u0003אמר\u0004 אותו שכיב מרע: \u0003\"אף כתובו וחתומו והבו ליה\"\u0004 \u0005[כתבו וחתמו ותנו לו],\u0006 שניכר מדבריו שהציווי לכתוב בא כתוספת לעצם המתנה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003רב יהודה אמר שמואל\u0004 בענין זה, \u0003הלכה: כותבין ונותנין. וכן אמר רבא אמר רב נחמן, הלכה: כותבין ונותנין\u0004 במקרה זה.","אדם בריא \u0003הכותב נכסיו לבניו\u0004 בחייו, אבל רוצה להשתמש בהם עד מותו — \u0003צריך שיכתוב \"מהיום ולאחר מיתה\",\u0004 אלו \u0003דברי\u0004 \u0003ר' יהודה.\u0004 \u0003ר' יוסי אומר: אינו צריך\u0004 לכתוב \"מהיום\", ודיו שיכתוב שהוא מקנה את הנכסים לאחר מותו.","\u0003הכותב נכסיו לבנו\u0004 מהיום \u0003לאחר מותו\u0004 — \u0003האב אינו יכול למכור\u0004 את הנכסים הללו, \u0003מפני שהן כתובין\u0004 כבר בשטר מתנה \u0003לבן, והבן אינו יכול למכור\u0004 אותם, \u0003מפני שהן\u0004 עדיין \u0003ברשות האב\u0004 להשתמש בהם ולאכול את פירותיהם.","אם \u0003מכר האב\u0004 את הנכסים הללו — הרי הם \u0003מכורים\u0004 לקונה לאכול את פירותיהם בלבד \u0003עד שימות\u0004 האב, שאז הם עוברים לחלוטין לרשותו של הבן. ולהיפך, אם \u0003מכר הבן\u0004 בחיי האב — \u0003אין ללוקח בהן\u0004 זכות שימוש של \u0003כלום עד שימות האב.\u0004","ושואלים: \u0003וכי כתב\u0004 \u0005[וכאשר\u0006 הוא \u0005כותב]\u0006 \u0003\"מהיום ולאחר מיתה\" מאי הוי\u0004 \u0005[מה נהיה\u0006\u0005],\u0006 מה מועיל בכך? \u0003הא תנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]:\u0006 הכותב בגט שהוא יחול \u0003\"מהיום ולאחר מיתה\"\u0004 — הרי זה \u0003גט ואינו גט\u0004 גמור, \u0003ו\u0004לפיכך \u0003אם מת\u0004 האיש הזה ואין לו בנים, הרי זה ספק אם אשתו חייבת בייבום, ולכן היא \u0003חולצת ולא מתייבמת!\u0004","ומשיבים: \u0003התם מספקא לן אי תנאה הוי\u0004 \u0005[שם\u0006 בגט \u0005מסופק לנו אם\u0006 \"ולאחר מיתה\" \u0005תנאי הוא],\u0006 שהגט חל מעכשיו, אלא שהדבר מתגלה למפרע רק לאחר שימות, \u0003אי\u0004 \u0005[או]\u0006 \u0003חזרה הוי\u0004 \u0005[הוא],\u0006 שחזר בו מדבריו שאמר \"מהיום\" והתכוון שיחול רק לאחר מיתה, ואז אינה יכולה להתגרש. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בשטר מתנה, שני הדברים יכולים להתקיים, ואפשר להבין כי \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003גופא קני\u0004 \u0005[\u0006את \u0005גוף\u0006 הקרקע \u0005קנה]\u0006 \u0003מהיום, פירא\u0004 \u0005[\u0006את \u0005הפירות]\u0006 קנה \u0003לאחר מיתה.\u0004","שנינו במשנה ש\u0003ר' יוסי אומר: אינו צריך\u0004 לכתוב \"מהיום ולאחר מיתה\". מסופר: \u0003רבה בר אבוה חלש\u0004 \u0005[חלה].\u0006 \u0003על לגביה\u0004 \u0005[נכנסו אצלו]\u0006 \u0003רב הונא ורב נחמן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרב נחמן, בעי מיניה\u0004 \u0005[שאל אותו]:\u0006 האם \u0003הלכה כר' יוסי\u0004 בענין זה, \u0003או אין הלכה כר' יוסי? אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003טעמיה\u0004 \u0005[\u0006את \u0005טעמו]\u0006 של \u0003ר' יוסי\u0004 בהלכה זו \u0003לא ידענא\u0004 \u0005[איני יודע],\u0006 \u0003הלכה איבעי מיניה\u0004 \u0005[אשאל ממנו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את בעי מיניה אי\u0004 \u0005[אתה שאל ממנו\u0006 רק ה\u0005אם]\u0006 \u0003הלכה\u0004 כר' יוסי \u0003אי\u0004 \u0005[או]\u0006 \u0003לא,\u0004 \u0003וטעמיה אנא אמינא\u0004 \u0005[ו\u0006את \u0005טעמו אני אומר]\u0006 \u0003לך.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 רב נחמן את רבה בר אבוה שאלה זו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר אבוה, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב:\u0004 \u0003הלכה כר' יוסי. בתר דנפקו\u0004 \u0005[אחר שיצאו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרב נחמן: \u0003היינו טעמיה\u0004 \u0005[זהו טעמו]\u0006 של \u0003ר' יוסי\u0004 שאינו צריך לכתוב \"מהיום ולאחר מיתה\", \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003זמנו של שטר,\u0004 העובדה שמופיע בשטר תאריך הכתיבה \u0003מוכיח עליו\u0004 שרצונו שהמתנה תחול כבר מהיום. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך]\u0006 כהסבר זה של רב הונא, \u0003ר' יוסי אומר: אינו צריך\u0004 לכתוב \"מהיום ולאחר מיתה\", \u0003מפני שזמנו של שטר מוכיח עליו.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 אם נתן האב את נכסיו לבנו לאחר מותו \u0003בהקנאה,\u0004 שעשה מעשה קנין, \u0003מהו\u0004 הדין? האם צריך לכתוב \"מהיום\"? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בהקנאה\u0004 — \u0003אינו צריך\u0004 לכתוב \"מהיום\".","\u0003רב פפי אמר: איכא אקניתא\u0004 \u0005[יש הקניה]\u0006 ש\u0003צריך\u0004 לכתוב \"מהיום\", \u0003ואיכא אקניתא\u0004 \u0005[ויש הקניה]\u0006 ש\u0003לא צריך.\u0004 ובאופן זה: אם נכתב בשטר \u0003\"אקנייה וקנינא מיניה\"\u0004 \u0005[\"הקנה לו וקנינו ממנו\"]\u0006 — \u0003לא צריך\u0004 לכתוב \"מהיום\". ואם נכתב בשטר בסדר הפוך \u0003\"קנינא מיניה ואקנייה\"\u0004 \u0005[\"קנינו ממנו והקנה\"]\u0006 — \u0003צריך.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חנינא מסורא: מי איכא מידי, דאנן לא ידעינן וספרי ידעי\u0004 \u0005[האם יש דבר, שאנו\u0006 החכמים \u0005איננו יודעים והסופרים יודעים]?\u0006 שחילוק זה בין המקרה, שכתב \"קנינא\" לפני \"וקנינא מיניה\", או אחר כך, לא ידעוהו חכמים. מסופר: \u0003שאלונהו לספרי\u0004 \u0005[שאלו אותם, את הסופרים]\u0006 של \u0003אביי וידעי\u0004 \u0005[וידעו],\u0006 \u0003ולספרי\u0004 \u0005[ואת הסופרים]\u0006 של \u0003רבא\u0004 — \u0003וידעי\u0004 \u0005[ו\u0006גם הם \u0005ידעו].\u0006","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: בין\u0004 שהיה הנוסח \u0003\"אקנייה וקנינא מיניה\"\u0004 \u0005[\"הקנה לו וקנינו ממנו\"],\u0006 \u0003בין \"קנינא מיניה ואקנייה\"\u0004 \u0005[\"קנינו ממנו והקנה לו\"]\u0006 — \u0003לא צריך\u0004 לכתוב \"מהיום\", לפי שנזכר בו קנין, \u0003ואילו\u0004 \u0003ב\u0004מקרה שנכתב רק: \u0003\"דוכרן פתגמי דהוי באנפנא\"\u0004 \u0005[\"זכרון דברים שהיה לפנינו\"],\u0006 ולא הוזכר קנין — \u0003פליגי\u0004 \u0005[\u0006בזה \u0005נחלקו]\u0006 ר' יהודה ור' יוסי האם צריך לכתוב בו \"מהיום\".","\u0003אמר רב כהנא: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה\u0006 הזו \u0005לפני]\u0006 \u0003רב זביד מנהרדעא, ואמר לי: אתון הכי מתניתו לה\u0004 \u0005[אתם כך אתם שונים אותה],\u0006 במהלך של שאלה ותשובה ומחלוקת בפרטי הדברים, \u0003אנן הכי מתנינן לה\u0004 \u0005[אנו כך אנו שונים אותה],\u0006 כאמירה ישירה ורצופה: \u0003אמר רבא אמר רב נחמן: בהקנאה\u0004 — \u0003אינו צריך\u0004 לומר \"מהיום\"; \u0003בין\u0004 שהיה הנוסח \u0003\"אקנייה וקנינא מיניה\"\u0004 \u0005[\"הקנה לו וקנינו ממנו\"],\u0006 \u0003בין \"קנינא מיניה ואקנייה\"\u0004 \u0005[\"קנינו ממנו והקנה לו\"]\u0006 — \u0003לא צריך\u0004 לכתוב \"מהיום\" ואילו \u0003ב\"דוכרן פתגמי דהוו באנפנא\"\u0004 \u0005[ב\"זכרון דברים שהיו בפנינו\"]\u0006 — \u0003פליגי\u0004 \u0005[\u0006בזה \u0005נחלקו]\u0006 ר' יהודה ור' יוסי האם צריך או לא צריך.","שנינו במשנה: \u0003הכותב נכסיו לבנו לאחר מותו,\u0004 שניהם אינם יכולים למכור מפני שהקרקע שייכת במידה מסויימת לשניהם. ובאותו ענין \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003מכר הבן\u0004 את הקרקע \u0003בחיי האב, ומת הבן בחיי האב\u0004 — מה הדין?"],["\u0003אמר\u0004 \u0003ר' יוחנן: לא קנה\u0004 ה\u0003לוקח\u0004 את גוף הקרקע לאחר מות האב, \u0003וריש לקיש אמר: קנה לוקח.\u0004","ומסבירים את טעמיהם: \u0003ר' יוחנן אמר: לא קנה לוקח,\u0004 שלדעתו \u0003קנין\u0004 ה\u0003פירות כקנין הגוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שכיון שיש לאב זכות הנאה מכל פירות הנכס הריהו נחשב כבעלים בגוף הנכס, ולכן כל עוד לא מת לא יכול היה הבן להקנותו בשלימות ללוקח זה.","\u0003וריש לקיש אמר: קנה לוקח\u0004 כאשר ימות האב, כי הוא סבור ש\u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 וקנין הגוף בלא הפירות עומד לעצמו, ולכן יכול היה הבן למוכרו, והלוקח זוכה בו לבסוף.","ושואלים: \u0003והא איפליגו\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו]\u0006 \u0003בה\u0004 בשאלה זו \u0003חדא זימנא\u0004 \u0005[פעם אחת]!\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003המוכר שדהו לפירות\u0004 ולא מכר את גוף השדה — \u0003ר' יוחנן אמר:\u0004 הקונה \u0003מביא\u0004 ביכורים מן השדה הזה \u0003וקורא\u0004 עליהם את \"מקרא ביכורים\", הפסוקים שצריך לומר בשעת הבאת הביכורים. \u0003וריש לקיש אמר:\u0004 הקונה \u0003מביא\u0004 אמנם ביכורים משדה זה, \u0003ו\u0004אולם \u0003אינו קורא\u0004 את \"מקרא ביכורים\".","והסברנו: \u0003ר' יוחנן אמר\u0004 ש\u0003מביא וקורא,\u0004 כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 ולכן הלוקח את השדה לפירותיה הרי הוא כבעלים על גוף השדה, והריהו כמביא ביכורים מאדמתו שלו. \u0003וריש לקיש אמר: מביא ואינו קורא,\u0004 משום שלדעתו \u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 וכיון שאין גוף הקרקע שלו אינו יכול לומר \"האדמה אשר נתת לי\". ומדוע הוצרכו לחזור ולחלוק באותו עקרון עצמו?","ומשיבים: הוצרכו החכמים לפרש מחלוקתם לא רק לגבי ביכורים, אלא גם במקרה שלנו, כי \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003ר' יוחנן: אף על גב דבעלמא\u0004 \u0005[אף על פי שבכלל]\u0006 \u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 כמבואר במחלוקת לענין ביכורים, \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי הבן שמכר בנכסי אביו, בכל זאת \u0003אצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005]\u0006 להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003אבא לגבי בריה אחולי אחיל\u0004 \u0005[האב אצל בנו מוחל]\u0006 לו את הזכות שמקנה לו קנין הפירות בגוף הקרקע, ונמצא שמכר הבן ללוקח קנין שלם בגוף הקרקע, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זה כך, וקנין הפירות שבידי האב כקנין הגוף הוא.","\u0003ור' שמעון בן לקיש אמר\u0004 \u0005[אומר]\u0006 לך: \u0003אף על גב דבעלמא\u0004 \u0005[אף על פי שבכלל]\u0006 \u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 ומי שמוכר לחבירו שדה לפירותיה אינו מוכר לו בכך דבר בגוף הקרקע, \u0003הכא אצטריך\u0004 \u0005[כאן\u0006 בכל זאת \u0005הוצרך]\u0006 גם כן לומר שאינו נחשב כקנין הגוף, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003כל\u0004 דבר שהוא \u0003לגבי נפשיה\u0004 \u0005[אצל עצמו]\u0006 כשמשייר לעצמו את קנין הפירות ומוכר לאחר את גוף הקרקע, \u0003אפילו במקום בריה\u0004 \u0005[בנו]\u0006 גם כשנותן את גוף הקרקע לבנו, \u0003נפשיה עדיפא ליה\u0004 \u0005[\u0006קנין \u0005עצמו עדיף לו],\u0006 והוא משאיר בידו את הזכות בגוף הקרקע, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זה כך.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו: המצווה \u0003\"נכסי לך, ואחריך,\u0004 אחרי מותך, \u0003יירש\u0004 אותם \u0003פלוני, ואחריו יירש פלוני\",\u0004 אם \u0003מת\u0004 ה\u0003ראשון\u0004 — \u0003קנה\u0004 ה\u0003שני, מת\u0004 ה\u0003שני\u0004 — \u0003קנה\u0004 ה\u0003שלישי,\u0004 אם","\u0003מת\u0004 ה\u0003שני בחיי\u0004 ה\u0003ראשון\u0004 — \u0003יחזרו\u0004 ה\u0003נכסים ליורשי\u0004 ה\u0003ראשון,\u0004 ואינם עוברים לשלישי. כי אין לשלישי זכות אלא מכח השני, ושני זה כבר מת לפני שזכה בהם.","\u0003ואם איתא\u0004 \u0005[יש]\u0006 ממש בדבריך, שקנין פירות אינו כקנין הגוף, אם כן יחזרו הנכסים \u0003ליורשי\u0004 ה\u0003נותן מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שהרי מתנת הנכסים לראשון (ולשני) לא היתה אלא קנין פירות, שישתמש בפירות הנכסים כל ימי חייו, ולאחר מכן יעברו לאחרים. ואם כן יחזרו הנכסים למי שיש בידו קנין הגוף בנכסים אלו — הבעלים הראשון או יורשיו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003כבר תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רב הושעיא בבבל: \"אחריך\" שאני\u0004 \u0005[שונה],\u0006 שכשנאמר כך הרי יש בזה נתינה גמורה לראשון, של הגוף והפירות יחד. \u0003וכן רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 זו \u0003רבה בר רב הונא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב, ואמר\u0004 לו רב בתשובה: \u0003\"אחריך\" שאני\u0004 \u0005[שונה].\u0006","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שאם מת השני, הרי במות הראשון \u0003יחזרו\u0004 הנכסים \u0003ליורשי\u0004 ה\u0003נותן!\u0004"],["ומשיבים: מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 במשמעות ההלכתית של \"אחריך\". \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר \u0003\"נכסי לך ואחריך לפלוני\", וירד\u0004 ה\u0003ראשון ומכר\u0004 את הנכסים \u0003ואכל\u0004 את פירותיהם — לאחר מותו של הראשון \u0003השני מוציא\u0004 את הנכסים \u0003מיד הלקוחות,\u0004 אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: אין לשני אלא מה ששייר\u0004 ה\u0003ראשון,\u0004 ומה שמכר — אינו חוזר.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא אחרת: האומר \u0003\"נכסי לך ואחריך לפלוני\"\u0004 — \u0003יורד\u0004 ה\u0003ראשון ומוכר ואוכל\u0004 לכתחילה, אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: אין לראשון אלא אכילת פירות בלבד.\u0004","ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבי\u0004 על דברי \u0003רבי, ו\u0004מדברי \u0003רבן שמעון בן גמליאל\u0004 על דברי \u0003רבן שמעון בן גמליאל,\u0004 שלכאורה שיטותיהם הפוכות מן הברייתא הראשונה!","ומשיבים: מדברי \u0003רבי\u0004 על דברי \u0003רבי לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר בברייתא הראשונה, שאם מכר אינו מכור, נאמר \u0003לגופא\u0004 \u0005[לגופו]\u0006 כשמכר את גוף השדה, \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמוכר ואוכל לכתחילה — \u0003לפירא\u0004 \u0005[\u0006כשמכר \u0005לפירות].\u0006 וכן מדברי \u0003רבן שמעון בן גמליאל\u0004 על דברי \u0003רבן שמעון בן גמליאל לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר בברייתא השניה שאין לראשון אלא אכילת פירות, מדובר \u0003לכתחלה, הא\u0004 \u0005[זה]\u0006 שאם מכר אין השני יכול להוציא מידו — \u0003דיעבד\u0004 \u0005[כשעשה\u0006 מעשה ומכר\u0005].\u0006","\u0003אמר אביי: איזהו רשע ערום?\u0004 — \u0003זה המשיא עצה למכור בנכסים כ\u0004דעת \u0003רבן שמעון בן גמליאל,\u0004 שהרי רבן שמעון בן גמליאל אינו אומר שיעשה כן לכתחילה, אלא שאין המעשה בטל בדיעבד, והנותן עצה למכור ולשלול את זכותו של השני הוא רשע ערום.","ובפסק ההלכה בענין זה \u0003אמר\u0004 \u0003ר' יוחנן: הלכה כרבן שמעון בן גמליאל\u0004 שאם עבר הראשון ומכר — אין לשני אלא מה ששייר ראשון. \u0003ומודה\u0004 הוא, \u0003שאם נתנן\u0004 הראשון לאדם אחר \u0003במתנת שכיב\u0004 \u0003מרע\u0004 — \u0003לא עשה כלום,\u0004 והשני מוציא מיד הקונה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר אביי: מתנת שכיב מרע לא קנה אלא לאחר מיתה, ו\u0004אולם קודם לכן, ברגע המיתה עצמו, \u0003כבר קדמו \"אחריך\",\u0004 כלומר, השני, שזכה בנכסים מכח נותן המתנה, שאמר כבר \"ואחריך לפלוני\".","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר אביי הכי\u0004 \u0005[כך]\u0006 שמתנת שכיב מרע לא נקנית אלא לאחר המיתה? \u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שחלקו בשאלה: \u0003מתנת שכיב מרע מאימתי קנה\u0004 המקבל? \u0003אביי אמר: עם גמר מיתה,\u0004 כלומר, ברגע המיתה עצמו, \u0003ורבא אמר: לאחר גמר מיתה!\u0004","ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003אביי מ\u0004ההלכה \u0003ההיא\u0004 שמתנת שכיב מרע חלה מיד במותו. ושואלים: \u0003ממאי דמההיא הדר ביה\u0004 \u0005[ממה,\u0006 מנין, \u0005שמאותה\u0006 הלכה \u0005חזר בו]?\u0006 \u0003דלמא מהא הדר ביה\u0004 \u0005[שמא מזו חזר בו]\u0006 והוא סבור שרק לאחר המיתה קנה!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, כי יש ראיה לשיטה זו ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 האומר לאשתו \u0003\"זה גיטך אם מתי\",\u0004 או שאמר \u0003\"זה גיטך מחולי זה\",\u0004 או \u0003\"זה גיטך לאחר מיתה\"\u0004 — בכל אלה \u0003לא אמר כלום,\u0004 שאין גט חל לאחר מות המגרש. ומכאן משמע שכל שמצווה אדם מחמת שהוא הולך למות — אין כוונתו שיחול אלא לאחר המיתה.","ועוד בפסקי הלכה בענין זה, \u0003אמר\u0004 \u0003ר' זירא אמר\u0004 \u0003ר' יוחנן: הלכה כרבן שמעון בן גמליאל\u0004 שאם מכר הראשון את הנכסים הריהם מכורים, \u0003ואפילו היו בהן עבדים והוציאן לחירות.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי אם ביכולתו למוכרם מדוע לא יוכל לשחררם! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אמר ליה\u0004 \u0005[\u0006יכול היה \u0005לומר לו]\u0006 הנותן: \u0003למיעבד איסורא\u0004 \u0005[לעשות איסור]\u0006 \u0003לא יהבינן\u0004 \u0005[נתתי אותם]\u0006 \u0003לך,\u0004 שאסור לשחרר עבדים לכתחילה, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' יוחנן שבכל זאת רשותו לעשות כן.","ועוד בענין זה \u0003אמר רב יוסף אמר\u0004 \u0003ר' יוחנן: הלכה כרבן שמעון בן גמליאל, ואפילו עשאן תכריכין למת.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שיכול היה הנותן לומר: \u0003לשוינהו\u0004 \u0005[לעשות אותם]\u0006 \u0003איסורי הנאה לא יהבי\u0004 \u0005[נתתי]\u0006 אותם \u0003לך,\u0004 אלא לשימוש והנאה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהנכסים ברשותו.","ודנים בענין הקשור לענייננו. \u0003דרש רב נחמן בר רב חסדא:\u0004 האומר לחבירו \u0003\"אתרוג זה נתון לך במתנה ואחריך לפלוני\", נטלו\u0004 ה\u0003ראשון ויצא בו,\u0004 כלומר, רצה לצאת בו ידי חובת מצות לולב. וביום טוב הראשון של סוכות צריך שיהו ארבעת המינים של הנוטל, ולא של אדם אחר — \u0003באנו\u0004 בכך \u0003למחלוקת רבי ורבן שמעון בן גמליאל\u0004 בטיב הקנין של הראשון. שלדעת רבי הואיל ואין הראשון יכול למכור מתנה מעין זו אלא לפירות — אינו קנוי לו לגמרי ואינו יוצא בו. ואילו לדעת רבן שמעון בן גמליאל שיכול למכור לגמרי — יוצא בו ידי חובתו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן בר יצחק: עד כאן לא פליגי\u0004 \u0005[נחלקו]\u0006 \u0003רבי ורבן שמעון בן גמליאל התם\u0004 \u0005[שם]\u0006\u0005,\u0006 \u0003אלא דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]\u0006 ש\u0003קנין פירות כקנין הגוף דמי\u0004 \u0005[נחשב],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, \u0005סבור]\u0006 ש\u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[נחשב].\u0006 \u0003אלא הכא\u0004 \u0005[כאן],\u0006"],["\u0003אי מיפק לא נפיק ביה, למאי יהביה ניהליה\u0004 \u0005[אם לצאת אינו יוצא בו, למה,\u0006 לאיזה צורך, \u0005נתן אותו לו]?\u0006 אלא ודאי מועילה נתינה זו לצאת ידי חובה.","\u0003אלא, מיפק\u0004 \u0005[לצאת]\u0006 — \u0003דכולי עלמא לא פליגי דנפיק ביה\u0004 \u0005[הכל אינם חלוקים שיוצא בו],\u0006 ואף לדעת רבי, אבל אם \u0003מכרה\u0004 הראשון \u0003או אכלה\u0004 — בזה \u0003באנו למחלוקת רבי ורבן שמעון בן גמליאל,\u0004 שלדעת רבי אם מכרו — נוטלו השני מן הקונים, ואם אכלו — צריך לתת לשני את דמיו. ולדעת רבן שמעון בן גמליאל מה שעשה עשוי, שהרי קנין הגוף יש לו בו.","\u0003אמר רבה בר רב הונא: האחין שקנו אתרוג בתפוסת הבית,\u0004 שלא חילקו עדיין ביניהם את נכסי אביהם שמת, ומתוך כסף הירושה של כולם קנו אתרוג, אם \u0003נטלו אחד מהן ויצא בו,\u0004 כלומר, על מנת לצאת בו חובת המצוה, בודקים אנו: \u0003אם יכול לאוכלו,\u0004 שהאחים מרשים לו לאוכלו — \u0003יצא\u0004 בנטילתו ידי המצוה, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לא יצא,\u0004 לפי שאינו שלו לגמרי, ואין יוצאים ביום הראשון של חג הסוכות ידי חובת המצוה אלא בארבעה מינים השייכים לו.","ומעירים: \u0003ודוקא דאיכא\u0004 \u0005[שיש]\u0006 \u0003אתרוג לכל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מהאחים — יצא, אם יכול לאוכלו, \u0003אבל\u0004 אם היה לכל אחד מהם רק \u0003פריש או רמון\u0004 — \u0003לא\u0004 יצא.","\u0003אמר רבא:\u0004 האומר לחבירו \u0003\"אתרוג זה נתון לך במתנה על מנת שתחזירהו לי\", נטלו ויצא בו\u0004 כלומר, נטלו כדי לצאת בו ידי מצות נטילה, אם לאחר מכן אכן \u0003החזירו\u0004 לנותן — \u0003יצא\u0004 ידי חובה, אבל אם \u0003לא החזירו\u0004 — \u0003לא יצא,\u0004 שהרי לא מילא את התנאי, ונמצא שלא היתה מתנה מתחילה. ומעירים: \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבא בכך ש\u0003מתנה על מנת להחזיר שמה מתנה,\u0004 וכל עוד היא בידו הרי היא שלו לגמרי.","ועוד בענין \"נכסי לך ואחריך לפלוני\", מסופר: \u0003ההיא איתתא דהוה\u0004 \u0005[אישה אחת שהיה]\u0006 \u0003לה דיקלא בארעא\u0004 \u0005[דקל בקרקעו]\u0006 של \u0003רב ביבי בר אביי. כל אימת דהות אזלא למיגזריה, הוה קפיד עילוה\u0004 \u0005[כל פעם שהיתה הולכת לקצוץ\u0006 את פירות הדקל, \u0005היה מקפיד עליה]\u0006 שהיא דורסת על הצמחים שלו. וכדי שלא יקפיד עליה החליטה לוותר לו לפי שעה על פירות הדקל, \u0003אקניתיה ניהליה\u0004 \u0005[הקנתה אותו לו]\u0006 ל\u0003כל שני\u0004 (שנות) \u0003חייו,\u0004 כדי שאחר מותו תוכל לקבל בחזרה את הדקל, \u0003אזל איהו אקנייה ניהליה\u0004 \u0005[הלך הוא\u0006 ו\u0005הקנה אותו\u0006 את הדקל\u0005]\u0006 \u0003לבנו\u0004 ה\u0003קטן,\u0004 כדי שאי אפשר יהיה עוד להוציא מידו.","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 לרב ביבי בר אביי: \u0003משום דאתו ממולאי אמריתו מילי מוליאתא\u0004 \u0005[שבאים אתם,\u0006 שנולדתם \u0005מאנשים כרותים,\u0006 ממשפחת בני עלי, \u0005אומרים אתם דברים כרותים\u0006 שאין להם בסיס\u0005]?\u0006 שהרי \u0003אפילו רבן שמעון בן גמליאל לא קאמר\u0004 \u0005[אומר]\u0006 במקרה של \"נכסי לך ואחריך לפלוני\", שמה שמכר הראשון מכור, \u0003אלא\u0004 כשהנותן אומר שלאחר הראשון יעבור הנכס \u0003ל\u0004אדם \u0003אחר, אבל\u0004 כאשר הוא אומר שלאחר מכן יחזיר את הנכס \u0003ל\u0004נותן \u0003עצמו\u0004 — \u0003לא,\u0004 ובוודאי לא הקנה למקבל את גוף הנכס כלל, שיוכל למוכרו, ואין במעשהו זה של רב ביבי בר אביי ולא כלום.","ועוד בענין זה \u0003אמר רבא אמר רב נחמן:\u0004 האומר לחבירו \u0003\"שור זה נתון לך במתנה על מנת שתחזירהו לי\",\u0004 אם \u0003הקדישו\u0004 המקבל \u0003והחזירו\u0004 — \u0003הרי זה מוקדש ומוחזר,\u0004 שחל ההקדש, וגם נחשב השור כמוחזר לבעלים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מאי אהדריה\u0004 \u0005[מה החזיר לו]?\u0006 שהרי שור זה אינו מוחזר לו ממש, משום שמוקדש הוא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003ומאי חסריה\u0004 \u0005[ומה חיסרו]?\u0006 הרי החזיר לו את גוף השור! \u0003אלא אמר רב אשי: חזינן\u0004 \u0005[רואים אנו],\u0006 מדייקים אנו בלשון התנאי: \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"על מנת שתחזירהו\"\u0004 — \u0003הא אהדריה\u0004 \u0005[הרי החזירו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"על מנת שתחזירהו לי\"\u0004 — הרי \u0003מידי דחזי ליה קאמר ליה\u0004 \u0005[דבר שראוי לו אמר לו],\u0006 ולכן אם הקדישו אינו נחשב להחזרה, ובטלו משום כך המתנה וההקדש.","\u0003אמר רב יהודה אמר שמואל: הכותב נכסיו לאחר\u0004 במתנה, \u0003ואמר הלה\u0004 המקבל \u0003\"אי אפשי\u0004 (אין רצוני) \u0003בהן\"\u0004 — \u0003קנה\u0004 המקבל את הנכסים, \u0003ואפילו עומד וצווח\u0004 שאינו רוצה בהם. \u0003ור' יוחנן אמר: לא קנה\u0004 אם אינו מסכים.","\u0003אמר\u0004 \u0003ר' אבא בר ממל, ולא פליגי\u0004 \u0005[נחלקו]\u0006 האמוראים בענין זה, אלא דיברו במקרים שונים:"],["\u0003כאן\u0004 בדברי ר' יוחנן, מדובר \u0003בצווח מעיקרא\u0004 \u0005[מתחילה]\u0006 שמיד כשנתן לו את שטר המתנה אמר שאינו רוצה, ובמקרה זה אכן הוא אינו קונה, \u0003כאן\u0004 — \u0003בשותק מעיקרא\u0004 \u0005[מתחילה]\u0006 בזמן שקיבל לידו את שטר המתנה, \u0003ולבסוף\u0004 רק לאחר מכן \u0003צווח\u0004 שאינו רוצה. שבמקרה זה כבר אין הדבר בידו, שכבר זכה בכך.","\u0003אמר רב נחמן בר יצחק: זיכה לו על ידי אחר, ושתק ולבסוף צווח\u0004 — \u0003באנו\u0004 בענין \u0003זה\u0004 \u0003למחלוקת רבן שמעון בן גמליאל ורבנן\u0004 \u0005[וחכמים],\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הכותב נכסיו לאחר והיו בהן עבדים, ואמר הלה \"אי אפשי\u0004 (אין רצוני) \u0003בהן\"\u0004 בעבדים האלה, \u0003אם היה רבן\u0004 (אדונם) ה\u0003שני,\u0004 כלומר, המקבל, \u0003כהן\u0004 — \u0003הרי אלו אוכלין בתרומה,\u0004 כעבדי כהן, שמה שאמר \"אי אפשי בהם\" אינו מועיל. \u0003רבן שמעון בן גמליאל אומר: כיון שאמר הלה \"אי אפשי בהן\"\u0004 — \u0003כבר זכו בהן יורשין\u0004 של הנותן, והם נחשבים כעבדים שלהם לכל ענין.","\u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה\u0004 בבריתא זו: \u0003ו\u0004כי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 סבור שזכה בהם השני \u0003אפילו עומד וצווח\u0004 שאינו רוצה במתנה זו?!","\u0003אמר רבא, ואיתימא\u0004 \u0005[ואם תאמר,\u0006 יש אומרים\u0005]\u0006 שאמר זאת \u0003ר' יוחנן: בצווח מעיקרו\u0004 בזמן הקבלה — \u0003דכולי עלמא\u0004 \u0005[הכל]\u0006 \u0003לא פליגי\u0004 \u0005[חולקים]\u0006 ש\u0003לא קני\u0004 \u0005[קונה].\u0006 ומן הצד האחר, כאשר \u0003שתק\u0004 מתחילה \u0003ולבסוף\u0004 כשקיבל \u0003צווח\u0004 שאינו רוצה — \u0003דכולי עלמא לא פליגי דקני\u0004 \u0005[הכל אינם חולקים שקונה].\u0006","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה במקרה \u0003שזיכה לו\u0004 את הנכסים \u0003על ידי אחר ו\u0004הוא היה שם ו\u0003שתק, ולבסוף\u0004 כשבאו הנכסים לידו \u0003צווח,\u0004 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003מדשתיק\u0004 \u0005[מכיון ששתק]\u0006 — \u0003קנינהו\u0004 \u0005[קנה אותם],\u0006 \u0003והאי דקא\u0004 \u0005[וזה שהוא]\u0006 \u0003צווח\u0004 — \u0003מהדר הוא דקא הדר ביה\u0004 \u0005[חוזר הוא בו]\u0006 לאחר מעשה הקנין, ואינו יכול לבטל את קניינו בדרך זו. ואם רצונו להיפטר מן העבדים יעשה זאת בדרך קניינית של מתנה, מכירה, או שחרור.","\u0003ורבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003הוכיח סופו\u0004 שצווח, \u0003על תחלתו,\u0004 שאף מתחילה לא רצה במתנה זו. \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא צווח עד השתא\u0004 \u0005[עכשיו],\u0006 משום \u0003דסבר\u0004 \u0005[שסבור\u0006 היה\u0005]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 עדיין \u0003לא מטו\u0004 \u0005[הגיעו]\u0006 הנכסים \u0003לידי,\u0004 לשם \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אצווח.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שכיב מרע שאמר \"תנו מאתים זוז לפלוני, ושלש מאות לפלוני, וארבע מאות לפלוני\"\u0004 — \u0003אין אומרין\u0004 בכגון זה: \u0003כל הקודם בשטר זוכה\u0004 תחילה, ורק ממה שנותר יזכה בו הבא אחריו. אלא אם אין די לכולם — הנכסים מתחלקים בין כולם באופן יחסי לחלקם במתנה. \u0003לפיכך,\u0004 הואיל ואין דין קדימה, לכן גם לענין חיובם, אם \u0003יצא עליו,\u0004 על הנותן, \u0003שטר חוב\u0004 לאחר מותו — בעל החוב \u0003גובה מכולם\u0004 (לפי חלקם במתנה) ואינו גובה תחילה מן האחרון.","\u0003אבל\u0004 אם \u0003אמר \"תנו מאתים זוז לפלוני, ואחריו לפלוני, ואחריו לפלוני\"\u0004 — \u0003אומרין\u0004 ש\u0003כל הקודם בשטר זוכה\u0004 תחילה, ואם נשאר — יזכה השני. \u0003לפיכך,\u0004 אם \u0003יצא עליו שטר חוב\u0004 — \u0003גובה\u0004 בעל חוב את כל החוב \u0003מן האחרון, אין לו\u0004 במה שקיבל האחרון כדי לכסות את כל החוב — \u0003גובה מ\u0004מי \u0003שלפניו, אין לו\u0004 לזה שלפניו — \u0003גובה משלפני פניו\u0004 כלומר, מהזוכה הראשון.","ועוד בענין מתנת שכיב מרע, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שכיב מרע שאמר\u0004 בשעת מותו \u0003\"תנו מאתים זוז לפלוני בני בכור כראוי לו\"\u0004 — הרי זה \u0003נוטלן\u0004 את מאתיים הזוז הללו, \u0003ו\u0004מזה \u0003נוטל\u0004 גם \u0003את\u0004 חלק \u0003בכורתו.\u0004 אבל \u0003אם אמר \"\u0004תנו לו מאתיים זוז \u0003בבכורתו\"\u0004 — אינו מקבל את שניהם, אבל \u0003ידו\u0004 של הבכור \u0003על העליונה,\u0004 כיצד? אם \u0003רצה\u0004 — \u0003נוטלן\u0004 את מאתיים הזוז, אם \u0003רצה\u0004 — \u0003נוטל\u0004 חלק \u0003בכורתו\u0004 ולא את מאתיים הזוז.","\u0003ו\u0004כיוצא בזה \u0003שכיב מרע שאמר \"תנו מאתים זוז לפלונית אשתי כראוי לה\"\u0004 — \u0003נוטלתן\u0004 את מאתיים הזוז הללו, \u0003ונוטלת\u0004 גם \u0003את כתובתה,\u0004 שאנו מבינים שהוסיף לה מאתים זוז על הראוי לה בכתובה. ואולם \u0003אם אמר \"בכתובתה\"\u0004 —"],["\u0003ידה על העליונה,\u0004 אם \u0003רצה\u0004 (רצתה) — \u0003נוטלתן\u0004 את מאתיים הזוז, \u0003רצה\u0004 (רצתה) — \u0003נוטלת כתובתה.\u0004","\u0003ושכיב מרע שאמר \"תנו מאתים זוז לפלוני בעל חובי כראוי לו\"\u0004 — \u0003נוטלן\u0004 את מאתיים הזוז \u0003ונוטל\u0004 גם \u0003את חובו, ואם אמר \"בחובו\"\u0004 — \u0003נוטלן\u0004 אותם מאתיים זוז \u0003בחובו.\u0004","ותוהים: \u0003משום\u0004 ש\u0003אמר \"כראוי לו\", נוטלן ונוטל את חובו? ודלמא\u0004 \u0005[ושמא]\u0006 \u0003\"כראוי לו בחובו\" קאמר\u0004 \u0005[אומר הוא],\u0006 ולא נתכוון אלא לומר מה היה החוב!","\u0003אמר רב נחמן, אמר לי\u0004 רב \u0003הונא: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 — שיטת \u0003ר' עקיבא היא, דדייק לישנא יתירא\u0004 \u0005[ש\u0006הוא \u0005מדייק לשון יתירה]\u0006 ולומד ממנה להלכה:","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 המוכר את הבית — לא מכר \u0003לא את הבור ולא את הדות\u0004 (מאגר מים) שבתוכו, \u0003אף על פי שכתב לו\u0004 המוכר לקונה בשטר המכירה שמוכר לו גם \u0003עומקא ורומא\u0004 \u0005[עומק ורום]\u0006 של הבית, משום שהבור והדות הם דבר לעצמו ואינם בכלל הבית. \u0003וצריך\u0004 המוכר ששייר לעצמו את הבור \u0003ליקח\u0004 (לקנות) \u0003לו\u0004 מן הקונה זכות שימוש ב\u0003דרך\u0004 אל הבור והדות שלו, אלו \u0003דברי\u0004 \u0003ר' עקיבא.\u0004","\u0003וחכמים אומרים: אין צריך ליקח לו דרך,\u0004 שאנו מניחים שיחד עם הבור והדות שייר לעצמו גם דרך להגיע אליהם. \u0003ומודה\u0004 \u0003ר' עקיבא, בזמן שאמר לו \"חוץ מאלו\"\u0004 שכתב במפורש שמוכר את הבית חוץ מן הבור והדות — \u0003שאינו צריך ליקח לו דרך\u0004 מן הקונה, אלא שייר לעצמו גם את הזכות לדרך אליהם.","\u0003אלמא\u0004 \u0005[מכאן]\u0006 שלדעת ר' עקיבא, \u0003כיון\u0004 ש\u0003לא צריך\u0004 לומר \u0003וקאמר\u0004 \u0005[ו\u0006הוא \u0005אומר]\u0006 — \u0003לטפויי מלתא קאתי\u0004 \u0005[להוסיף דבר\u0006 \u0005הוא בא],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין בעל חוב, \u0003כיון\u0004 ש\u0003לא צריך\u0004 לומר \"כראוי לו\" \u0003וקאמר\u0004 \u0005[והוא אומר]\u0006 — \u0003לטפויי מלתא קא אתי\u0004 \u0005[להוסיף דבר הוא בא],\u0006 שנותן לו מאתיים זוז יתר על חובו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שכיב מרע שאמר \"מנה יש לי אצל פלוני\"\u0004 שהוא חייב לי — \u0003העדים כותבין\u0004 שכך אמר, ורשאים לעשות זאת \u0003אף על פי שאין מכירין\u0004 בדבר, ואינם יודעים אם אכן אותו אדם חייב לו. \u0003לפיכך\u0004 כיון שהדברים לא אומתו, \u0003כשהוא\u0004 היורש \u0003גובה\u0004 על פי מסמך זה זו — \u0003צריך להביא ראיה\u0004 שאותו אדם אכן חייב, אלו \u0003דברי\u0004 \u0003ר' מאיר; וחכמים אומרים: אין\u0004 העדים \u0003כותבין,\u0004 כלומר, רשאים לכתוב, \u0003אלא אם כן מכירין\u0004 שכך היה המעשה, \u0003לפיכך כשהוא גובה\u0004 — \u0003אין צריך להביא ראיה,\u0004 ככל שטר חוב החתום בעדים.","\u0003אמר רב נחמן, אמר לי\u0004 רב \u0003הונא: תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בלשון הפוכה, \u0003ר' מאיר אומר: אין כותבין, וחכמים אומרים: כותבין. ואף\u0004 \u0003ר' מאיר לא אמר\u0004 שאין כותבים \u0003אלא משום\u0004 חשש שיבוא השטר לפני \u0003בית דין טועין,\u0004 שיסמכו על הכתוב בשטר הזה בלי לדקדק בו, ויגבו על פיו בלא לדרוש ראיה נוספת. \u0003אמר רב דימי מנהרדעא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003אין חוששין לבית דין טועין,\u0004 שיסמכו על דברי שכיב מרע בענין כזה, בלא לדרוש ראיה נוספת. אלא העדים כותבים כפי שנאמר להם.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שאמר \u0003רבא?\u0004 ש\u0003אמר רבא: אין חולצין,\u0004 כלומר, אין עושים בית דין חליצה של אלמנה לאחי המת, \u0003אלא אם כן מכירין\u0004 שהאיש הוא היבם והאשה היא היבמה, \u0003ואין ממאנין,\u0004 אין קטנה שהשיאוה אחיה ממאנת בנישואיה אם רוצה בכך בפניהם, \u0003אלא אם כן מכירין\u0004 שהיא הילדה שנישאה ולמי היא נשואה. \u0003לפיכך\u0004 בית דין אחר \u0003כותבין גט חליצה וגט מיאון\u0004 לנשים אלו, על פי עדים שראו את המעשה, \u0003ואף על פי שאין מכירין.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמר רבא שאין בית דין חולצים וממאנים אלא אם כן מכירים? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003חוששין לבית דין טועין\u0004 שיכתבו גט בלי לברר האם החליצה והמיאון נעשו מתוך ידיעה וודאית?","ודוחים: \u0003לא,\u0004 אין להשוות בין הדברים, \u0003בית דין בתר בית דינא לא דייקי\u0004 \u0005[אחר בית דין\u0006 אחר \u0005אינם מדקדקים]\u0006 ולכן יש לחשוש שבית הדין השני יסמוך על כך שבית דין הראשון הכירו את הצדדים. אבל \u0003בית דינא בתר\u0004 \u0005[בית דין אחר]\u0006 \u0003עדים דייקי\u0004 \u0005[מדקדקים],\u0006 ולפיכך אין לחשוש שיסמכו בטעות על דבר שנעשה בלא ידיעה ברורה.","בהמשך למשנה הקודמת, העוסקת באב הכותב את נכסיו לבנו לאחר מותו, נאמר כי \u0003האב תולש\u0004 מפירות אותם נכסים \u0003ומאכיל\u0004 (נותן) \u0003לכל מי שירצה, ו\u0004כן כל \u0003מה שהניח\u0004 בשעת מותו כשהוא \u0003תלוש\u0004 — \u0003הרי הוא של\u0004 כל ה\u0003יורשין\u0004 של האב, ואינו שייך לבן זה בלבד.","מלשון המשנה מדייקים: מה שהניח \u0003תלוש\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 הריהו של יורשים, אבל אם היה \u0003מחובר\u0004 לקרקע — \u0003לא,\u0004 אלא של אותו בן הוא."],["\u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 שבמעשה כגון זה, \u0003שמין את המחוברין ללוקח\u0004 ונותן את דמיהם ליורשים. משמע שאף בהיותם מחוברים שייכים הפירות לכל יורשי האב!","\u0003אמר עולא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 במשנתנו, מדובר \u0003בבנו\u0004 שזוכה גם בפירות המחוברים לקרקע שניתנה לו כשמת האב, \u0003כאן\u0004 בברייתא, מדובר \u0003באחר\u0004 שקנה מבן זה. וטעם ההבדל הוא — \u0003הואיל ודעתו של אדם קרובה אצל בנו\u0004 ובוודאי התכוון להשאיר לו יחד עם הקרקע את הפירות המחוברים לה. מה שאין כן באדם אחר שהבן מכר לו — אינו מתכוון לכך.","\u0003הניח\u0004 הנפטר \u0003בנים גדולים וקטנים\u0004 — \u0003אין הגדולים מתפרנסין\u0004 לצרכי לבושם וכסותם \u0003על ידי\u0004 (על חשבון) ירושת אחיהם \u0003הקטנים, ולא הקטנים נזונין\u0004 (מקבלים מזונם) \u0003על\u0004 חשבון אחיהם \u0003הגדולים, אלא חולקין\u0004 את הירושה \u0003בשוה,\u0004 ויתנו לקטנים ולגדולים לכל אחד לפי צרכיו מתוך חלקו שלו.","אם \u0003נשאו הגדולים\u0004 נשים ועשו את צרכי החופה מכספי הירושה הכללית — \u0003ישאו\u0004 גם \u0003הקטנים\u0004 נשים באותו אופן. \u0003ואם אמרו קטנים: הרי אנו נושאין כדרך שנשאתם אתם\u0004 בעבר, כשהיה אבינו חי — \u0003אין שומעין להם, אלא מה שנתן להם אביהם\u0004 לראשונים \u0003נתן,\u0004 ואלו אינם יכולים ליטול יתר על חלקם בירושה.","וכן אם \u0003הניח\u0004 הנפטר \u0003בנות גדולות וקטנות\u0004 ולא היו לו בנים, שאז הבנות יורשות כבנים — \u0003אין\u0004 הבנות \u0003הגדולות מתפרנסות\u0004 בלבוש וכיוצא בו \u0003על ידי\u0004 (על חשבון) חלק \u0003הקטנות, ולא הקטנות נזונות\u0004 מזונותיהן \u0003על\u0004 חשבון \u0003הגדולות, אלא חולקות\u0004 את כל הנכסים \u0003בשוה\u0004 וכל אחת נוטלת מחלקה.","\u0003נשאו\u0004 (נישאו) \u0003ה\u0004\u0003גדולות\u0004 ולקחו לצורך הדבר גם מן הירושה הכללית — \u0003ישאו\u0004 כמותן ה\u0003קטנות.\u0004 אבל \u0003אם אמרו\u0004 ה\u0003קטנות: הרי אנו נושאות כדרך שנשאתם אתם\u0004 בחיי האב — \u0003אין שומעין להן.\u0004","\u0003זה חומר בבנות\u0004 יורשות \u0003מבבנים\u0004 יורשים: \u0003שהבנות נזונות על\u0004 חשבון \u0003הבנים\u0004 שכן הוא מתנאי כתובת אימם, \u0003ואין נזונות על\u0004 חשבון \u0003הבנות\u0004 האחרות.","ובקשר למה שנאמר במשנה, שהאחים הגדולים אינם מתפרנסים בכסות מחלק האחים הקטנים, \u0003אמר רבא: האי\u0004 \u0005[אותו]\u0006 \u0003גדול אחי\u0004 \u0005[האחים]\u0006 \u0003דלבש ואיכסי מביתא\u0004 \u0005[שלובש ומתכסה מתוך\u0006 רכוש \u0005הבית\u0006 הכלל י המשותף לכל האחים\u0005]\u0006 — \u0003מאי דעבד עבד\u0004 \u0005[מה שעשה עשה]\u0006 ואין גובים ממנו לאחר מכן מה שלקח מן הירושה הכללית.","ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין\u0004 \u0003הגדולים מתפרנסין על הקטנים!\u0004 ומשיבים: \u0003מתניתין\u0004 \u0003בשרכא\u0004 \u0005[משנתנו\u0006 מדברת \u0005באדם בטל],\u0006 שכיון שאינו עוסק בענייני הבית — אין הצדקה להלבישו מן הירושה הכללית. מה שאין כן בדברי רבא, גדול האחים עוסק בענייני כל המשפחה, ולכן ראוי לו שיתלבש כראוי לתועלת כל האחים.","ותוהים: \u0003שרכא, פשיטא\u0004 \u0005[אדם בטל, פשוט]\u0006 הדבר שאינו רשאי לקחת מהירושה, שהרי אין לאחיו כל הנאה מכך, ומדוע יתנו לו מהרכוש הכללי? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחא להו\u0004 \u0005[נוח להם]\u0006 ש\u0003לא נינוול\u0004 \u0005[יתנוול],\u0006 ומשום כבודם רוצים שגם הוא יתלבש כהוגן, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במשנה, שאינו יכול לדרוש זאת, ואם לקח מן הירושה הכללית — יצטרך להחזיר לאחיו את חלקם.","שנינו במשנה: \u0003נשאו גדולים ישאו הקטנים.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 מה כוונת הדברים?","\u0003אמר רב יהודה, הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר,\u0006 זו כוונתו\u0005]:\u0006 אם \u0003נשאו גדולים\u0004 נשים \u0003לאחר מיתת אביהן\u0004 ולקחו לשם כך מהירושה הכללית — \u0003ישאו קטנים\u0004 גם כן נשים ויקחו מהירושה הכללית \u0003לאחר מיתת אביהן, אבל\u0004 אם \u0003נשאו גדולים בחיי אביהן, ואמרו קטנים לאחר מיתת אביהן: \"הרי אנו נושאין כדרך שנשאתם אתם\"\u0004 — \u0003אין שומעין להן, אלא מה שנתן להן אביהן\u0004 לגדולים בחייו \u0003נתן,\u0004 ואין הקטנים יכולים לתבוע אותו סכום שניתן לגדולים.","שנינו במשנה שאם \u0003הניח בנות גדולות וקטנות\u0004 וכו' נשאו גדולות — ישאו קטנות. מהלכה זו מביאים ראיה לענין הבא: \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003אבוה בר גניבא לרבא, ילמדנו רבינו:\u0004 אשה ש\u0003לוותה\u0004 כספים בעל פה (ולא בשטר) \u0003ואכלה\u0004 במעות אלו, \u0003ו\u0004לפני שנתבעה לשלם \u0003עמדה ונשאת\u0004 והכניסה רכושה לבעלה כנהוג, האם ה\u0003בעל לוקח הוי\u0004 \u0005[הוא\u0006 נחשב\u0005]\u0006 כאילו קנה ממנה את הנכסים, \u0003או יורש הוי\u0004 \u0005[הוא\u0006 נחשב\u0005]?\u0006","ומשמעות ההבדל לענייננו: האם \u0003לוקח הוי\u0004 \u0005[הוא\u0006 נחשב\u0005],\u0006 והואיל \u0003ומלוה על פה אינו גובה מן הלקוחות\u0004 — אי אפשר לגבות מן הבעל את מה שלוותה אשתו קודם נישואיה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003יורש הוי\u0004 \u0005[הוא\u0006 נחשב\u0005]\u0006 בנכסיה, \u0003ומלוה על פה גובה מן היורשין?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא, \u0003תנינא\u0004 \u0005[שנינו]\u0006 תשובה לדבר זה במשנתנו: \u0003נשאו גדולות\u0004 — \u0003ישאו קטנות; מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שאם \u0003נשאו גדולות\u0004 נכסים \u0003לבעל\u0004 מן הירושה הכללית, לצרכי חופה — \u0003ישאו קטנות מבעל?\u0004 כלומר, שיכולות הקטנות כשהן נישאות לתבוע סכום זה גם מבעלי אחיותיהן הגדולות? ואם כן — דין יורש יש לבעל, שהרי הבנות הגדולות מילוה (על פה) נטלו מן הנכסים!","ודוחים: \u0003לא,\u0004 יש לפרש: \u0003נשאו גדולות לבעל\u0004 — \u0003ישאו\u0004 גם \u0003קטנות לבעל\u0004 צרכי חופה מן הירושה הכללית. אבל אין ללמוד מכאן על האפשרות לגבות דבר מן הבעל.","ותוהים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]?\u0006 \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 במפורש, כמו שפירש רבא את המשנה: \u0003נשאו גדולות לבעל\u0004 — \u0003ישאו קטנות מבעל!\u0004","ומשיבים: גם אם כך יש להבין את משנתנו, אין מכאן ראיה למקרה שאשה לוותה בעל פה, \u0003דלמא שאני\u0004 \u0005[שמא שונה]\u0006 \u0003פרנסה\u0004 של הבנות העומדות להינשא, שאין דינה כמילוה על פה, לפי \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003לה קלא\u0004 \u0005[קול],\u0006 שהכל יודעים שחלק מנכסיו של אדם שמת משועבד לפרנסת הבנות, ולפיכך דין מילוה שבשטר יש לה. וגם אם הבעל נחשב לוקח — כאן יגבו ממנו הבנות הקטנות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא, לאו היינו\u0004 \u0005[האם לא זהו]\u0006 ש\u0003שלח רבין באגרתיה\u0004 \u0005[במכתבו]\u0006 מארץ ישראל: \u0003מי שמת והניח אלמנה ובת\u0004 — \u0003אלמנתו נזונת מנכסיו,\u0004 וגם אם \u0003נשאת הבת\u0004 — \u0003אלמנתו\u0004 ממשיכה להיות \u0003נזונת מנכסיו,\u0004 אף שהם כעת בידי בעלה של הבת. אם \u0003מתה הבת\u0004 וירש אותה הבעל — \u0003אמר רב יהודה בן אחותו של\u0004 \u0003ר' יוסי בר' חנינא, על ידי היה מעשה\u0004 שהובא לפני חכמים מקרה כזה, \u0003ואמרו: אלמנתו\u0004 של אותו אדם עדיין \u0003נזונת מנכסיו\u0004 של בעל הבת שמתה.","ומעתה: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003יורש הוי\u0004 \u0005[הוא]\u0006 הבעל, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אלמנתו\u0004 של חמיו \u0003נזונת מנכסיו,\u0004 כיון שהוא היורש של נכסי המת (דרך אשתו, בת המת) ועדיין שיעבודה של האלמנה מוטל עליו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003לוקח הוי\u0004 \u0005[הוא]\u0006 בנכסי אשתו, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003נזונת\u0004 האלמנה \u0003מנכסיו?\u0004 הרי אין גובים מלקוחות לצורך מזונות האלמנה!","\u0003אמר אביי: אי לאו דשלח\u0004 \u0005[אם לא שהיה שולח]\u0006 \u0003רבין\u0004 דבר זה, \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003לא ידעינן\u0004 \u0005[היינו יודעים]\u0006 שהבעל יורש? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003אלו הן\u0004 הדברים \u0003שאין חוזרין ביובל: הבכורה,\u0004 כלומר, חלק הבכורה אינו חוזר ומתחלק לכל האחים כמו שאר נכסי אביהם שמת, אלא נשאר ביד הבכור,"],["\u0003והיורש את אשתו\u0004 לאחר מותה, שאין הנכסים חוזרים למשפחתה. שאין הבעל נחשב כלוקח, שהרי לוקח מחזיר את הקרקע ביובל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והשתא\u0004 \u0005[ועכשיו]\u0006 שהוא \u0003שלח\u0004 את הדבר הזה \u0003מי ידעינן\u0004 \u0005[האם\u0006 אכן \u0005יודעים אנו]\u0006 שדין הבעל כדין יורש? \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' יוסי בר' חנינא: באושא התקינו\u0004 תקנה זו, \u0003האשה שמכרה נכסי מלוג,\u0004 כלומר, נכסים השייכים לה, ובעודה נשואה יש לבעלה זכות לאכול מהם, אם מכרתם \u0003בחיי בעלה ומתה\u0004 — \u0003הבעל מוציא\u0004 את הנכסים גופם \u0003מיד הלקוחות.\u0004 משמע שדינו כלוקח ולא כיורש, שהרי לוקח מוציא מיד לקוח שאחריו, אבל יורש אינו יורש נכסים שמכר המוריש בחייו!","\u0003אלא\u0004 יש להבין את הענין באופן אחר, \u0003אמר רב אשי: בעל\u0004 — \u0003שויוהו רבנן\u0004 \u0005[עשו אותו חכמים]\u0006 \u0003כיורש, ושויוהו רבנן\u0004 \u0005[ועשו אותו חכמים]\u0006 \u0003כלוקח, והיכא דטבא ליה עבדו ליה\u0004 \u0005[והיכן שטוב לו עשו לו],\u0006 כדין זה או זה. כיצד? — \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003יובל\u0004 — \u0003שויוהו רבנן\u0004 \u0005[עשו אותו חכמים]\u0006 \u0003כיורש משום פסידא דידיה\u0004 \u0005[ההפסד שלו],\u0006 שלא יצטרך להחזיר. \u0003גבי\u0004 \u0005[אצל\u0006 המקרה\u0005]\u0006 של \u0003ר' יוסי בר' חנינא\u0004 שמכרה אשתו נכסים בחייו — \u0003שויוהו רבנן\u0004 \u0005[עשו אותו חכמים]\u0006 \u0003כלוקח משום פסידא דידיה\u0004 \u0005[הפסד שלו],\u0006 אלא \u0003גבי\u0004 \u0005[אצל]\u0006 של \u0003רבין\u0004 לגבי מזונות אלמנת חמיו — \u0003משום פסידא\u0004 \u0005[הפסדה]\u0006 של ה\u0003אלמנה שויוהו רבנן\u0004 \u0005[עשו אותו חכמים]\u0006 \u0003כיורש.\u0004","ושואלים: אם אנו מתחשבים בהפסדם של אחרים, \u0003והא גבי\u0004 \u0005[והרי אצל\u0006 אותו דין\u0005]\u0006 שהזכיר \u0003ר' יוסי בר' חנינא\u0004 באשה שמכרה בחיי בעלה, שהבעל מוציא מיד הלקוחות, מדובר במקרה \u0003דאיכא פסידא\u0004 \u0005[שיש\u0006 בו \u0005הפסד]\u0006 \u0003ללקוחות, ו\u0004בכל זאת \u0003שויוהו רבנן\u0004 \u0005[עשו אותו חכמים]\u0006 \u0003כלוקח!\u0004","ומשיבים: \u0003התם אינהו אפסידו אנפשייהו\u0004 \u0005[שם הם\u0006 הלקוחות \u0005הפסידו לעצמם],\u0006 ש\u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003בעל, לא איבעי להו למיזבן מאיתתא דיתבא תותי גברא\u0004 \u0005[היו צריכים לקנות מאשה היושבת תחת בעלה],\u0006 ולהפקיע מידו.","","\u0003מי שמת והניח בנים ובנות, בזמן שהנכסים מרובין\u0004 — \u0003הבנים יירשו\u0004 את הנכסים, \u0003והבנות יזונו\u0004 מאותם הנכסים, לפי תנאי הכתובה. אם היו \u0003נכסים מועטין\u0004 שאינם מספיקים לכל — \u0003הבנות יזונו\u0004 מהם, \u0003והבנים ישאלו על הפתחים\u0004 (יקבצו נדבות) אם אין להם דרך אחרת להשיג מזונות. \u0003אדמון אומר:\u0004 וכי \u0003בשביל שאני זכר הפסדתי?!\u0004 וראוי שבכל מקרה יזונו גם הבנים! \u0003אמר רבן גמליאל: רואה\u0004 (מצדיק) \u0003אני את דברי אדמון.\u0004","ושואלים: \u0003וכמה\u0004 הם נכסים \u0003מרובין? אמר רב יהודה אמר רב: כדי שיזונו מהן אלו ואלו\u0004 הבנים וגם הבנות \u0003שנים עשר חדש. כי אמריתא קמיה\u0004 \u0005[כאשר אמרתי\u0006 דבר זה \u0005לפני]\u0006 \u0003שמואל, אמר: זו דברי רבן גמליאל בר רבי, אבל חכמים אומרים:\u0004 נכסים מרובים הם \u0003כדי שיזונו מהן אלו ואלו עד שיבגרו\u0004 הבנות.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר\u0004 בשם \u0003ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל שיזונו מהן אלו ואלו עד שיבגרו\u0004 — \u0003הן מרובין, פחות מכאן\u0004 — \u0003הרי אלו מועטין.\u0004","ושואלים: \u0003ואי ליכא\u0004 \u0005[ואם אין]\u0006 מספיק \u0003לאלו ואלו עד שיבגרו,\u0004"],["אבל יש יותר מכפי סיפוקן של הבנות לצרכיהן, בכל זאת \u0003שקלי להו\u0004 \u0005[יקחו להן]\u0006 ה\u0003בנות לכולהו\u0004 \u0005[את הכל]?\u0006 מדוע? \u0003אלא אמר רבא: מוציאין להן מזונות לבנות עד שיבגרו, והשאר,\u0004 כל מה שמעבר לכך — הרי הוא \u0003לבנים.\u0004","\u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 שאם היו הנכסים \u0003מרובין ו\u0004אחר כך \u0003נתמעטו\u0004 — \u0003כבר זכו בהן יורשין,\u0004 כלומר, הבנים, בזמן שהיו מרובים, והרי הם ברשותם, ויתנו מהם מזונות לבנות. אבל אם היו הנכסים \u0003מועטין\u0004 ולא ניתנו ביד הבנים \u0003ו\u0004אחר כך \u0003נתרבו מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 וצדדי השאלה: האם נאמר כי מבחינה מהותית גם נכסים מועטים \u0003ברשות\u0004 ה\u0003יורשין\u0004 הבנים \u0003קיימי\u0004 \u0005[\u0006הם \u0005עומדים],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003ברשות יורשין שבוח\u0004 \u0005[הושבחו],\u0006 ולכן הם חוזרים ומקבלים את מה שנתרבה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003סלוקי מסלקי\u0004 \u0005[מסולקים]\u0006 ה\u0003יורשין מהכא\u0004 \u0005[מכאן],\u0006 מן הנכסים המועטים, ומה שנתרבה, נתרבה לצורך הבנות?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר ר' אסי אמר ר' יוחנן: יתומין שקדמו ומכרו בנכסים מועטין\u0004 שהוריש אביהם, למרות שאינם רשאים לעשות כן — \u0003מה שמכרו מכרו.\u0004 ומכאן משמע שהנכסים המועטים אינם יוצאים לגמרי מרשות הבנים אף על פי שבפועל אינם רשאים להשתמש בהם, ומכאן שאם השביחו השביחו להם.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003ר' ירמיה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו וקא בעי מיניה\u0004 \u0005[ושואל היה ממנו]:\u0006 \u0003אלמנתו\u0004 של אדם, שמזונותיה מוטלים על היורשים, \u0003מהו שתמעט בנכסים?\u0004 כלומר, האם לוקחים בחשבון מזונות אלו כדי להגדיר את הנכסים כנכסים מועטים? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כך: \u0003כיון דאית\u0004 \u0005[שיש]\u0006 \u0003לה מזוני\u0004 \u0005[מזונות]\u0006 מן הירושה — \u0003ממעטא\u0004 \u0005[ממעטת],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003אילו מנסבא\u0004 \u0005[תינשא]\u0006 \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 מזונות, \u0003השתא נמי לית\u0004 \u0005[עכשיו גם כן,\u0006 לצורך הגדרת הנכסים, \u0005אין]\u0006 \u0003לה\u0004 ואינה ממעטת?","ושאלה נוספת: \u0003אם תמצא לומר,\u0004 כצד השני, ש\u0003כיון\u0004 ש\u0003אילו מנסבא לית\u0004 \u0005[תינשא אין]\u0006 \u0003לה השתא נמי לית\u0004 \u0005[עכשיו גם כן אין],\u0006 \u0003לה\u0004 ואינה ממעטת בנכסים, יש לשאול: \u0003בת אשתו\u0004 מנישואין קודמים, שהיתנה הבעל שתתפרנס מרכושו במשך שנים אחדות (ואין התחייבות זו בטלה גם לאחר מותו או עם נישואיה), \u0003מהו שתמעט בנכסים? מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כך: \u0003כיון דכי מנסבא נמי אית\u0004 \u0005[שכאשר\u0006 היא \u0005נישאת גם כן יש]\u0006 \u0003לה\u0004 שלא כמו אלמנה — \u0003וממעטא\u0004 \u0005[ו\u0006לכן היא כן \u0005ממעטת],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003אילו\u0004 היתה \u0003מתה לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 — \u0003ו\u0004לכן היא \u0003לא ממעטא\u0004 \u0005[ממעטת],\u0006 אין להכניס את מזונותיה בחישוב ערך הנכסים?","\u0003ואם תמצא לומר\u0004 כצד השני, \u0003כיון\u0004 ש\u0003אילו\u0004 היתה \u0003מתה לית\u0004 \u0005[אין]\u0006 \u0003לה ולא ממעטא\u0004 \u0005[ממעטת],\u0006 \u0003בעל חוב\u0004 של האב \u0003מהו שימעט בנכסים? מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דכי מיית נמי אית ליה\u0004 \u0005[שאם ימות גם כן יש לו],\u0006 שהרי יורשיו יגבו את החוב, לכן הוא \u0003ממעט, או דלמא כיון דמחסרי גוביינא לא\u0004 \u0005[שמא כיון שמחוסרים גבייה אינו]\u0006 \u0003ממעט?\u0004 זה היה נוסח אחד של הדברים.","\u0003ואיכא דבעי לה לאידך גיסא\u0004 \u0005[ויש ששאל את השאלה לצד האחר],\u0006 כלומר, התחיל את השאלות מצד זה: \u0003בעל חוב מהו שימעט בנכסים?\u0004"],["\u0003בת אשתו מהו שתמעט בנכסים? אלמנתו מהו שתמעט בנכסים?\u0004 ושאלה נוספת: אדם שלא השאיר בנים, אלא \u0003אלמנתו ובת,\u0004 ואין מזונות מספיקים לשתיהן, \u0003אי זה מהן קודמת?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003זיל האידנא ותא למחר\u0004 \u0005[לך עכשיו ובוא למחר]\u0006 שאני צריך להרהר בדבר. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 למחרת, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פשוט מיהת חדא\u0004 \u0005[פתור לפחות אחת]\u0006 מן הבעיות הללו, ש\u0003אמר ר' אבא אמר ר' אסי: עשו\u0004 מעמדה של \u0003אלמנה אצל הבת\u0004 \u0003כ\u0004מעמדה של \u0003בת אצל אחין בנכסים מועטין; מה בת אצל אחין\u0004 — \u0003הבת ניזונת והאחין ישאלו על הפתחים, אף\u0004 כשיש \u0003אלמנה אצל הבת\u0004 — \u0003אלמנה ניזונת והבת תשאל על הפתחים.\u0004","שנינו במשנה ש\u0003אדמון אומר: \"בשביל שאני זכר הפסדתי\"? וכו'.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]\u0006 מה עומד מאחרי טענתו? \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003בשביל שאני זכר, וראוי אני לעסוק בתורה, הפסדתי\u0004 שאצטרך במקום זה לחזר על הפתחים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אלא מעתה\u0004 שזהו הנימוק, \u0003מאן דעסיק\u0004 \u0005[מי שעוסק]\u0006 \u0003בתורה הוא דירית\u0004 \u0005[שיורש],\u0006 מי ש\u0003לא עסיק\u0004 \u0005[עוסק]\u0006 \u0003בתורה לא ירית\u0004 \u0005[יורש]?\u0006 והרי אין דין הירושה תלוי במעלתו של הבן! \u0003אלא אמר רבא, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003בשביל שאני זכר, וראוי אני לירש בנכסים מרובין\u0004 את הכל, והבנות יקבלו מזונות בלבד, האם \u0003הפסדתי בנכסים מועטין\u0004 את כל חלקי?","מי שמת ו\u0003הניח בנים ובנות וטומטום\u0004 (שהוא ספק זכר ספק נקבה, ושמא אינו לא זה ולא זה), \u0003בזמן שהנכסים מרובין\u0004 — \u0003הזכרים דוחין אותו אצל נקבות,\u0004 ואומרים לו: לא זכר אתה, ולא תירש בנכסים. אם יש \u0003נכסים מועטין\u0004 — \u0003הנקבות דוחות אותו אצל זכרים\u0004 ואומרות לו: אין אתה נקבה, ואינך זכאי להתחלק עמנו במזונות.","\u0003האומר\u0004 \u0003\"אם תלד אשתי זכר\u0004 — \u0003יטול מנה\",\u0004 הרי אם \u0003ילדה זכר\u0004 — \u0003יטול מנה.\u0004 ואם אמר \u0003\"\u0004אם תלד אשתי \u0003נקבה\u0004 — תטול \u0003מאתים\",\u0004 ו\u0003ילדה נקבה\u0004 — \u0003נוטלת מאתים.\u0004","אמר \u0003\"אם זכר\u0004 — \u0003מנה, אם נקבה\u0004 — \u0003מאתים\", וילדה זכר ונקבה\u0004 — \u0003זכר נוטל מנה, נקבה נוטלת מאתים.\u0004 אם \u0003ילדה טומטום\u0004 — \u0003אינו נוטל\u0004 כלל. \u0003אם אמר \"כל מה שתלד אשתי יטול\"\u0004 סכום כלשהו — \u0003הרי זה יטול\u0004 גם אם הוא טומטום. \u0003ו\u0004עוד אמרו: \u0003אם אין שם יורש אלא הוא\u0004 טומטום זה — \u0003יורש את הכל.\u0004","שנינו שאם היו נכסים מרובים הזכרים דוחים את הטומטום אצל הבנות. ושואלים: \u0003דוחין אותו ושקיל\u0004 \u0005[ו\u0006הוא \u0005נוטל]\u0006 מזונות \u0003כבת? הא קתני סיפא\u0004 \u0005[הרי שנה\u0006 ב\u0005סוף\u0006 המשנה\u0005]:\u0006 אם \u0003ילדה טומטום\u0004 — \u0003אינו נוטל,\u0004 משמע שאינו נדון אף כנקבה! \u0003אמר אביי: דוחין אותו ואין לו\u0004 כלום, כמו בסיפא.","\u0003ורבא אמר: דוחין אותו ויש לו\u0004 חלק בין הבנות. \u0003וסיפא אתאן\u0004 \u0005[ו\u0006ב\u0005סוף\u0006 המשנה, משם משמע שאין לו כלום, \u0005הגענו]\u0006 לשיטה אחרת — \u0003ל\u0004שיטת \u0003רבן שמעון בן גמליאל, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בענין מי שהקדיש עובריה של בהמתו, אם זכר — לשם קרבן עולה, ואם נקבה — לשם קרבן שלמים, \u0003ילדה טומטום\u0004 או \u0003אנדרוגינוס\u0004 — \u0003רבן שמעון בן גמליאל אומר: אין קדושה חלה עליהן\u0004 כלל","\u0003.\u0004 אם כן, יוצא שלדעתו טומטום ואנדרוגינוס הם בגדר בריות לעצמן, שאינן לא זכר ולא נקבה, ולכן גם במשנתנו אינו נוטל. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על אביי ממה ששנינו בברייתא: \u0003טומטום יורש כבן וניזון כבת; בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004פי שיטת \u0003רבא,\u0004 אפשר לומר כך: \u0003יורש כבן\u0004 — כשיש \u0003נכסים מועטין,\u0004 שדוחות אותו הבנות, ואינו יורש כשם שהבן אינו יורש, \u0003וניזון כבת\u0004 — כשיש \u0003נכסים מרובין,\u0004 שהבנים דוחים אותו מן הירושה, והוא רק ניזון כבת."],["\u0003אלא לאביי מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ניזון כבת\"?\u0004 הלא לדעת אביי אינו ניזון! ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003לרבא מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"יורש כבן\"?\u0004 והרי רבא מודה שאינו יורש! \u0003אלא\u0004 הכוונה היא: \u0003ראוי לירש ואין לו\u0004 בפועל, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין שניזון כבת, הכוונה היא: \u0003ראוי לזון ואין לו\u0004 משום שהבנות דוחות אותו.","שנינו במשנה כדוגמה: \u0003האומר \"אם ילדה אשתי זכר\u0004 יטול מנה אם נקבה יטול מאתיים \u0003\".\u0004 ועל השימוש בדוגמה זו שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003בת עדיפא ליה\u0004 \u0005[עדיפה לו]\u0006 לאדם \u0003מבן? והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחאי: כל שאינו מניח בן ליורשו\u0004 — \u0003הקדוש ברוך הוא מלא עליו עברה\u0004 (כעס, זעם) \u0003שנאמר: \"והעברתם את נחלתו לבתו\"\u0004 (במדבר כז, ח), \u0003ואין \"העברה\" אלא\u0004 לשון \u0003\"עברה\", שנאמר: \"יום עברה היום ההוא\"\u0004 (צפניה א, טו)!","ומשיבים: אין זו קושיה, \u0003לענין ירושה\u0004 — \u0003בן עדיף ליה\u0004 \u0005[לו]\u0006 שרצונו שישאר אחריו בן שישא את שמו, ולא תעבור נחלתו לשבט אחר. \u0003לענין הרווחה\u0004 כאשר הוא צריך להחליט במי מילדיו לתמוך כדי לעשות את חייו נוחים — \u0003בתו עדיפא ליה\u0004 \u0005[עדיפה לו].\u0006 שכיון שאינה יכולה לעבוד בכל מקום ובכל עבודה כבן, זקוקה היא יותר לסיוע, ולכן מובן שנותן לה סכום גדול יותר.","\u0003ושמואל אמר: הכא\u0004 \u0005[כאן]\u0006 שאומר \"אם תלד אשתי\" וכו' — \u0003במבכרת\u0004 (באשה שיולדת בראשונה) \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003וכ\u0004דברי \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: בת\u0004 שנולדת \u0003תחלה סימן יפה לבנים.\u0004 ומסבירים את טעם הדבר: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 משום \u0003דמרביא לאחהא\u0004 \u0005[ש\u0006היא \u0005מגדלת את אחיה]\u0006 הקטנים ממנה, ולכן בת ראשונה יש בה משום סימן יפה וטובה לאחיה. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003דלא שלטא ביה עינא בישא\u0004 \u0005[שאין שולטת בו\u0006 באביה \u0005עין רעה]\u0006 שנולד לו בן בכור. \u0003אמר רב חסדא: ולדידי בנתן עדיפן לי מבני\u0004 \u0005[ולי\u0006 \u0005עצמי הבנות עדיפות מן הבנים],\u0006 משום שהיו חתניו גדולי הדור.","ומוסיפים, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא מני\u0004 \u0005[זו\u0006 משנתנו המעדיפה את הבת, כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יהודה היא.\u0004","ושואלים: \u0003הי\u0004 \u0005[\u0006ל\u0005איזה]\u0006 מדברי \u0003ר' יהודה\u0004 מתכוונים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 לדברי \u0003ר' יהודה\u0004 בענין \u0003\"בכל\", דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"וה' ברך את אברהם בכל\"\u0004 (בראשית כד, א) — \u0003ר' מאיר אומר:\u0004 הברכה היתה \u0003שלא היה לו בת,\u0004 ולא היה מודאג בכל הבעיות הכרוכות בכך. \u0003ר' יהודה אומר:\u0004 הברכה היתה \u0003שהיתה לו בת, ו\"בכל\" שמה.\u0004 ודוחים: מכאן אין ראיה, כי \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' יהודה\u0004 שאומר שם ש\u0003ברתא נמי\u0004 \u0005[בת גם כן]\u0006 \u0003לא חסריה רחמנא\u0004 \u0005[חיסרו ה']\u0006 \u0003לאברהם,\u0004 והשלים המצווה בהולידו בנים ובת, אבל \u0003דעדיפא\u0004 \u0005[ש\u0006היא \u0005עדיפה]\u0006 \u0003מבן מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 אומר?","\u0003אלא הא\u0004 \u0005[זו]\u0006 מדברי \u0003ר' יהודה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אף שאין חובה גמורה (שבית דין כופים עליה) שיזון האב את ילדיו הגדולים, מכל מקום \u0003מצוה לזון את הבנות, וקל וחומר לבנים,\u0004 שמצוה יתירה לזון אותם, משום \u0003דעסקי\u0004 \u0005[ש\u0006הם \u0005עוסקים]\u0006 \u0003בתורה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: מצוה לזון את הבנים, וקל וחומר לבנות,\u0004 כדי ש\u0003לא ליתזלן\u0004 \u0005[תהיינה מזולזלות]\u0006 בחיפוש אחר מזונותיהן. ואם כן, ר' יהודה, לענין תמיכה — מעדיף את הבת על הבן.","ושבים לגופה של ההלכה ששנינו במשנתנו, שהאומר \"אם זכר מנה אם נקבה מאתים\", וילדה זכר ונקיבה, זכר נוטל מנה ונקיבה מאתים, ושואלים: \u0003אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ילדה זכר ונקבה\u0004 — \u0003הזכר נוטל ששה דינרין\u0004 של זהב, שהם מאה וחמישים דינרי כסף, \u0003והנקבה נוטלת שני דינרין\u0004 שהם חמישים דינרי כסף, \u0003במאי\u0004 \u0005[במה]\u0006 מדובר?","\u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי את ההלכה\u0006 הזו \u0005לפני]\u0006 \u0003רב כהנא,\u0004 וכך אמר לי: מדובר כאן \u0003במסרס,\u0004 כלומר, במערבב את דבריו, ש\u0003אמר\u0004 כך: אם תלד \u0003זכר תחלה\u0004 — הרי אני נותן לו \u0003מאתים, נקבה\u0004 שתיוולד \u0003אחריו\u0004 אינה מקבלת \u0003ולא כלום.\u0004 אם \u0003נקבה\u0004 תיוולד \u0003תחלה\u0004 — הרי היא מקבלת \u0003מנה, זכר אחריה\u0004 — יקבל \u0003מנה. וילדה זכר ונקבה, ולא ידעינן הי מינייהו נפק ברישא\u0004 \u0005[ואין אנו יודעים איזה מהם יצא בתחילה].\u0006 במקרה זה \u0003זכר שקיל\u0004 \u0005[נוטל]\u0006 \u0003מנה, ממה נפשך\u0004 \u0005[מ\"מה רצונך\"],\u0006 כלומר, מכל צד שהוא, שהרי אף אם היה נולד שני הבטיח לו מנה. \u0003אידך מנה הוה\u0004 \u0005[המנה האחר הריהו]\u0006 \u0003ממון המוטל בספק,\u0004 שאין יודעים מי מהם נולד קודם, \u0003ו\u0004לפיכך \u0003חולקין\u0004 ביניהם, והבן מקבל חמישים והבת חמישים.","וחוזרים ושואלים: \u0003והא דתניא\u0004 \u0005[וזו ששנינו\u0006 בברייתא\u0005]\u0006 אחרת: אם \u0003ילדה זכר ונקבה\u0004 \u0003אין לו אלא מנה, היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 \u0003אמר רבינא:\u0004 מדובר שם \u0003ב\"מבשרני\".\u0004 ומהו אותו מקרה? —"],["\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אדם האומר \u0003\"המבשרני במה נפטר\u0004 (מה יצא מן) \u0003רחמה של אשתי\",\u0004 אם אמר \u0003\"אם זכר\u0004 תלד — הרי \u0003יטול\u0004 המבשר \u0003מנה\",\u0004 אם \u0003ילדה זכר נוטל מנה,\u0004 אם אמר \u0003\"אם\u0004 תוליד \u0003נקבה מנה\"\u0004 — \u0003ילדה נקבה נוטל מנה, ילדה זכר ונקבה\u0004 — \u0003אין לו אלא מנה.\u0004","ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"זכר ונקבה\" לא אמר,\u0004 הרי לא אמר מה יעשה אם ייוולדו זכר ונקבה, ומדוע יטול מנה? ומשיבים: הכוונה היא ש\u0003אמר נמי\u0004 \u0005[גם כן]\u0006 \u0003\"אם זכר ונקבה\u0004 יחד תלד, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003יטול מנה\".\u0004 ושואלים: \u0003אלא למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 כיון שאמר שבכל מקרה יטול המבשר מנה, מה בא להוציא, שלא יקבל עליו דבר? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003נפל,\u0004 שאם יבשר לו שהיה זה נפל, על זה לא יקבל.","ובענין ההלכה המופיעה במשנתנו, מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר לה לדביתהו\u0004 \u0005[לאשתו]:\u0006 \u0003נכסי להאי דמעברת\u0004 \u0005[לזה\u0006 לעובר \u0005שאת מעוברת\u0006 בו\u0005],\u0006 \u0003אמר רב הונא: הוי\u0004 \u0005[הרי זה]\u0006 \u0003מזכה לעובר, והמזכה לעובר לא קנה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן לרב הונא\u0004 ממה ששנינו במשנתנו: \u0003האומר \"אם ילדה אשתי זכר יטול מנה\"\u0004 — \u0003ילדה זכר נוטל מנה,\u0004 ולפי דבריך כיון שהעובר עדיין לא \u0003בעולם אינו צריך ליטול כלום!\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003משנתינו איני יודע מי שנאה,\u0004 כלומר, איני יודע כשיטת מי היא, שתמוהה השיטה בעיני וסבור אני שהיא משובשת, לפי שהעובר איננו בעולם כך שניתן יהא להקנות לו.","ושואלים: ומדוע ענה רב הונא בדרך כזו? \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]:\u0006 שיטת ר' \u0003מאיר היא,\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם!\u0004","ודוחים: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את ר' \u0003מאיר\u0004 שאומר שאפשר להקנות דבר שלא בא לעולם (כגון פירות שעדין לא צמחו) \u0003לדבר ש\u0004הוא עצמו \u0003ישנו בעולם,\u0004 אבל להקנות \u0003לדבר שאינו בעולם מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]?\u0006","ושואלים עוד: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 רב הונא: משנתנו שיטת ר' \u0003יוסי היא,\u0004 ש\u0003אמר: עובר קני\u0004 \u0005[קונה]!\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 בת ישראל הנשואה לכהן, ונתעברה ממנו, ומת הכהן, הרי ה\u0003עובר פוסל\u0004 את עבדי אביו שמת מלאכול בתרומה, כיון שבמעי אמו אינו נחשב לכהן המאכיל בתרומה, ועבדים אלה הם ירושתו. \u0003ו\u0004כן \u0003אינו מאכיל\u0004 את אמו תרומה. אלו \u0003דברי ר'\u0004 \u0003יוסי.\u0004 הרי שלשיטתו העובר פוסל משום שהוא יורש את הנכסים!","ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003ירושה\u0004 שאינה כמו כל מתנה, כיון שהיא מתנה \u0003הבאה מאיליה\u0004 לרשות היורש, בלא שייעשה שום מעשה של קנין, ולכן העובר קונה. אבל כאן מדובר בהקנאה לעובר.","ושואלים עוד: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 רב הונא שמשנתנו שיטת ר' \u0003יוחנן בן ברוקה היא, דאמר\u0004 \u0005[שאומר]:\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003ירושה\u0004 הבאה מאליה \u0003ולא שנא\u0004 \u0005[שונה]\u0006 \u0003מתנה\u0004 שאדם נותן מעצמו ליורשו, דין אחד להם! \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר'\u0004 \u0003יוחנן בן ברוקה אומר:\u0004 המוריש כל נכסיו לאדם אחד, \u0003אם אמר\u0004 \u0003על מי שראוי ליורשו\u0004 — \u0003דבריו קיימין!\u0004","ודוחים: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את ר' \u0003יוחנן בן ברוקה\u0004 שאומר שנותן מתנה \u0003לדבר שישנו בעולם,\u0004 אבל \u0003לדבר שאינו בעולם מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו\u0006 כך\u0005]:\u0006 משנתנו ר' \u0003יוחנן בן ברוקה היא,\u0004 שמשווה מתנה לירושה, \u0003וסבר לה\u0004 \u0005[וסבור הוא]\u0006 \u0003כר'\u0004 \u0003יוסי\u0004 לענין עובר שנחשב כמי שראוי ליורשו! ודוחים: \u0003מי יימר דסבר לה\u0004 \u0005[מי יאמר ש\u0006הוא \u0005סובר]\u0006 כר' יוסי? שמא אינו סובר כר' יוסי!","ושואלים עוד: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 רב הונא שאין מדובר במשנתנו שאמר שהעובר הוא שיטול, אלא \u0003ב\"מבשרני\",\u0004 שהמבשר על לידתו יטול. ונמצא שאין מדובר כלל במזכה לעובר! ודוחים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003דקתני סיפא\u0004 \u0005[\u0006מה \u0005ששנה\u0006 ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003ואם אין שם יורש אלא הוא\u0004 — \u0003יורש הכל.\u0004 ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003ב\"מבשרני\"\u0004 מדובר, \u0003יורש מאי עבידתיה\u0004 \u0005[מה מעשיו]?\u0006 הרי אין זה יורש!","ועוד שואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 שבמשנתנו מדובר \u0003בשילדה\u0004 אשתו. כלומר, שלא אמר דבר זה כשהיה הילד עובר, אלא לאחר שכבר נולד, אלא שאינו יודע אם זכר או נקבה הוא! ודוחים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003דקתני סיפא\u0004 \u0005[\u0006מה \u0005ששנה\u0006 ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003ואם אמר \"כל מה שתלד אשתי יטול\"\u0004 — \u0003הרי זה יטול,\u0004 הלשון \u0003\"כל שתלד\"\u0004 אינה נכונה, \u0003\"כל שילדה\" מיבעי ליה\u0004 \u0005[צריך היה\u0006 לו לומר\u0005]!\u0006"],["ועוד שואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 רב הונא לרב נחמן, שמשנתנו, שמזכה בה לעובר, מתפרשת כגון \u0003דאמר\u0004 \u0005[שאומר]\u0006 שתחול הזכיה לעובר \u0003לכשתלד\u0004 ובמקרה זה אינו מקנה לעובר אלא בשעה שהוא כבר בעולם! ומשיבים: \u0003רב הונא\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב הונא: אף\u0004 המקנה לעוברה של אשה \u0003לכשתלד\u0004 — \u0003לא קנה.\u0004","וכפי שמצאנו שנחלקו בדבר, ש\u0003אמר רב נחמן: המזכה לעובר לא קנה,\u0004 אבל אם הוא מזכה לעובר \u0003לכשתלד\u0004 — \u0003קנה. ורב הונא אמר: אף לכשתלד\u0004 — \u0003לא קנה,\u0004 לפי שבשעה שזוכה לו אינו קיים בעולם. \u0003ורב ששת אמר: אחד זה ואחד זה,\u0004 בין שזוכה לעובר קודם לידתו ובין לאחר לידתו — \u0003קנה.\u0004","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 שעובר קונה? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גר שמת\u0004 ואין לו צאצאים, \u0003ובזבזו\u0004 (בזזו) \u0003ישראל נכסיו,\u0004 שהרי נכסיו הם כהפקר לכל, \u0003ושמעו\u0004 אחר כך \u0003שיש לו בן או שהיתה אשתו מעוברת\u0004 — \u0003חייבין להחזיר\u0004 את הנכסים למקומם. אם \u0003החזירו הכל, ואחר כך שמעו שמת בנו או שהפילה אשתו,\u0004 מי ש\u0003החזיק ב\u0004פעם ה\u0003שניה\u0004 לאחר שנודע הדבר — \u0003קנה,\u0004 אבל מי שהחזיק \u0003ב\u0004פעם ה\u0003ראשונה,\u0004 קודם שנודע שיש לו יורש — \u0003לא קנה.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה\u0006 על \u0005דעתך]\u0006 לומר ש\u0003עובר\u0004 עצמו \u0003לא קני\u0004 \u0005[אינו קונה],\u0006 \u0003למה להו אחזוקי\u0004 \u0005[להם להחזיק]\u0006 \u0003ב\u0004פעם ה\u0003שניה?\u0004 \u0003הא אחזיקו להו חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005החזיקו להם\u0006 בנכסים \u0005פעם אחת]!\u0006","\u0003אמר אביי\u0004 לדחות את ראייתו של רב ששת: \u0003ירושה הבאה מאיליה שאני\u0004 \u0005[שונה].\u0006 העובר אכן יורש, אבל רב ששת עוסק במזכה לעובר בקנין, ולא ניתן להקנות לעובר. \u0003רבא אמר: שאני התם\u0004 \u0005[שונה שם]\u0006 בענין בוזזי נכסי הגר, \u0003דרפוי מרפיאן בידייהו מעיקרא\u0004 \u0005[ש\u0006הנכסים \u0005רפויים בידם מתחילה],\u0006 שמתחילה לא ידעו בבירור אם יש לו יורשים, ולכן החזקתם הראשונה אינה נחשבת, וצריכים הם לחזור ולזכות.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה, אם זה או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]:\u0006 \u0003ש\u0004מתחילה \u0003שמעו בו\u0004 בעובר \u0003שמת\u0004 והחזיקו בנכסים, \u0003ו\u0004אולם באותה שעה \u0003לא\u0004 היה \u0003מת\u0004 \u0003ואחר כך מת.\u0004 שלטעמו של אביי, שהעובר קונה את ירושת אביו, הרי גם כאן, בשעה שהחזיקו לא היו הנכסים נכסי הפקר, ולא קנו. אבל לדעתו של רבא, שהדברים תלויים ברפיון החזקה, הרי במקרה זה, כששמעו בו שמת — החזיקו לגמרי, וכבר אז קנו את הנכסים.","ומביאים ראיה לשאלה אם עובר יורש: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003תינוק בן יום אחד נוחל\u0004 (יורש) נכסים, \u0003ומנחיל\u0004 נכסים ליורשיו. ונדייק מכאן: \u0003בן יום אחד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003עובר\u0004 — \u0003לא!\u0004 ודוחים: \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמר רב ששת:\u0004 הכוונה היא באותה משנה לדין אחר, שתינוק בן יומו \u0003נוחל בנכסי האם\u0004 ברגע שנולד, כדי \u0003להנחיל\u0004 אותם (גם אם מת לאחר יום) ליורשיו שאינם יורשי האם, כגון \u0003לאחין\u0004 שיש לו \u0003מן האב.\u0004 \u0003ו\u0004במקרה זה \u0003דוקא\u0004 כשהוא \u0003בן יום אחד\u0004 נוחל ומנחיל לאחיו מן האב, \u0003אבל עובר\u0004 שמתה אמו והותירה נכסים — \u0003לא\u0004 נוחל את אמו, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 —"],["לפי שבמקרה כזה שמדובר בו, \u0003מיית ברישא\u0004 \u0005[מת בראשונה]\u0006 לפני שמתה האם, מפני שלא יתכן שאשה מעוברת תמות ועוברה עדיין בחיים, משום שכוח החיות שבו קטן יותר, \u0003ואין הבן יורש את אמו\u0004 כשהוא \u0003בקבר להנחיל לאחין מן האב.\u0004 אבל במקרה אחר, כשאין מדובר בנכסי האם, יש לומר כי העובר יורש.","ותוהים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שברור ש\u0003הוא\u0004 העובר \u0003מיית ברישא\u0004 \u0005[מת\u0006 תמיד \u0005בראשונה]?\u0006 \u0003והא הוה עובדא\u0004 \u0005[והרי היה עובר]\u0006 שמתה אמו, \u0003ופרכס\u0004 העובר \u0003תלתא פרכוסי\u0004 \u0005[שלושה פרכוסים]\u0006 אחרי מות אמו! \u0003אמר מר בר רב אשי:\u0004 זו אינה ראיה, \u0003מידי דהוה\u0004 \u0005[כמו שקורה]\u0006 ב\u0003זנב הלטאה שמפרכסת,\u0004 שאין זה אומר שיש בה חיים, אלא הם תנועות של שרירים בלבד.","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר:\u0004 מה שאמרו באותה משנה שבן יום אחד נוחל ומנחיל, הכוונה היא \u0003לומר שממעט בחלק בכורה,\u0004 שכאשר מחלקים את הנכסים, מחשיבים אותו אילו היה קיים (למרות שכבר מת) ומקבל הבכור שני חלקים לפי חשבון זה. \u0003ו\u0004לענין זה \u0003דוקא בן יום אחד\u0004 ממעט בחלק הבכורה, \u0003אבל עובר\u0004 למרות שהוא יורש — בחלק הבכורה \u0003לא\u0004 ממעט, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003\"וילדו לו\"\u0004 (דברים כא, טו) \u0003אמר רחמנא\u0004 \u0005[הכתוב].\u0006","ודבר זה הוא כמו הלכה אחרת ש\u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: בן שנולד לאחר מיתת אביו\u0004 — \u0003אינו ממעט בחלק בכורה, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003\"וילדו לו\" אמר רחמנא\u0004 \u0005[הכתוב]\u0006 בענין ירושת הבכור, לומר שהבכור נוטל פי שנים ככל אחד מן האחים שכבר נולדו כשמת האב, \u0003והא ליכא\u0004 \u0005[והרי אין כאן].\u0006","ומעירים: \u0003בסורא מתנו הכי\u0004 \u0005[\u0006היו \u0005שונים כך]\u0006 כמו שלמדנו. \u0003בפומבדיתא מתנו הכי\u0004 \u0005[\u0006היו \u0005שונים כך]\u0006 בנוסח אחר: \u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: בכור שנולד לאחר מיתת אביו\u0004 — \u0003אינו נוטל פי שנים, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003\"יכיר\" אמר רחמנא\u0004 \u0005[הכתוב]\u0006 בענין הבכורה (\"כי את הבכור... יכיר\". דברים כא, יז), \u0003והא ליתא\u0004 \u0005[והרי אין]\u0006 אב ש\u0003יכיר.\u0004 ומסכמים: \u0003והלכתא ככל הני לישני\u0004 \u0005[והלכה ככל אותן לשונות]\u0006 ש\u0003אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא;\u0004 שתינוק בן יומו ממעט מחלק הבכורה, שבן שנולד לאחר מות אביו אינו ממעט בחלק הבכורה, ושבכור שנולד לאחר מות אביו אינו נוטל פי שנים.","ושבים לדון בענין האמור במשנתנו, שהאומר \"אם תלד אשתי זכר יטול מנה\" וכו'. \u0003אמר ר' יצחק אמר ר' יוחנן:\u0004 הלכה היא ש\u0003המזכה לעובר לא קנה. ואם תאמר: משנתינו,\u0004 הרי ממנה עולה שיכול לזכות לעובר! שם זהו מקרה מיוחד שנתנו חכמים תוקף לקנין כזה, \u0003הואיל ודעתו של אדם קרובה אצל בנו\u0004, אבל אין אדם יכול לזכות לעוברו של אדם אחר.","באותו ענין מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב חנא בגדתאה\u0004 \u0005[מבגדד]:\u0006 \u0003פוק אייתי\u0004 \u0005[צא\u0006 ו\u0005הבא]\u0006 \u0003לי בי\u0004 (מנין) \u0003עשרה, ואימר\u0004 \u0005[ואומר]\u0006 \u0003לך באפייהו\u0004 \u0005[בפניהם]\u0006 כדי שיתפרסם הדבר במעמד גדול: \u0003המזכה לעובר קנה.\u0004 ואולם מסכמים את ההלכה בגמרא באופן שונה, \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003המזכה לעובר לא קנה.\u0004","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר לדביתהו\u0004 \u0005[לאשתו]\u0006 עוד קודם שהיתה מעוברת: \u0003נכסי\u0004 יהיו \u0003לבני דיהוו\u0004 \u0005[לבנים שיהיו]\u0006 \u0003לי מיניך\u0004 \u0005[ממך].\u0006 \u0003אתא בריה קשישא\u0004 \u0005[בא בנו הגדול]\u0006 מנישואיו הקודמים, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ההוא גברא מאי תיהוי עליה\u0004 \u0005[אותו אדם מה יהא עליו]?\u0006 כלומר מה יהיה עלי, וכי אני לא אקבל דבר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל קני כחד מברא\u0004 \u0005[לך קנה\u0006 חלק \u0005כאחד מן הבנים\u0006 האחרים\u0005]\u0006 שייוולדו. ובפתרון בעיה זו פשוט לנו ש\u0003הנך\u0004 \u0005[אותם\u0006 הבנים\u0005]\u0006 שייוולדו לאחר מכן \u0003ודאי לא קנו\u0004 את הנכסים, ולא יטלו יותר מחלקם כיורשים, משום \u0003דאכתי ליתנהו\u0004 \u0005[שעדיין אינם]\u0006 בעולם.","ואולם לגבי \u0003האי\u0004 \u0005[זה]\u0006 הבן הגדול, יש לשאול: האם \u0003אית חולק לטליא\u0004 \u0005[יש חלק לנער]\u0006 \u0003במקום\u0004 שיש \u0003בניא\u0004 \u0005[בנים]\u0006 אחרים שיורשים. והוא מקבל, על סמך דבריו של אביו, חלק נוסף על המגיע לו מצד הירושה, \u0003או לית ליה חולק לטליא\u0004 \u0005[אין לו חלק\u0006 נוסף \u0005לנער]\u0006 \u0003במקום\u0004 שיש \u0003בניא\u0004 \u0005[בנים]?\u0006 \u0003ר' אבין ור' מיישא ור' ירמיה דאמרי\u0004 \u0005[שאמרו]:\u0006 \u0003אית חולק לטליא\u0004 \u0005[יש חלק לנער]\u0006 \u0003במקום\u0004 שיש \u0003בניא\u0004 \u0005[בנים].\u0006 \u0003ר' אבהו ור' חנינא בר פפי ור' יצחק נפחא דאמרי\u0004 \u0005[שאמרו]:\u0006 \u0003לית חולק לטליא\u0004 \u0005[אין חלק לנער]\u0006 \u0003במקום\u0004 שיש \u0003בניא\u0004 \u0005[בנים]\u0006\u0005.\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבהו לר' ירמיה:\u0004 האם \u0003הלכתא כוותן\u0004 \u0005[הלכה כמותנו],\u0006 \u0003או הלכתא כותייכו\u0004 \u0005[הלכה כמותכם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פשיטא דהלכתא כוותן\u0004 \u0005[פשוט שהלכה כמותנו],\u0006 \u0003דקשישנא מינייכו\u0004 \u0005[ש\u0006כן \u0005אנו זקנים מכם],\u0006 \u0003ולאו הלכתא כוותייכו דדרדקי אתון\u0004 \u0005[ואין הלכה כמותכם שצעירים אתם].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003מידי בקשישותא תליא מילתא\u0004 \u0005[וכי בזיקנה תלוי הדבר]?\u0006 הלא \u0003בטעמא תליא מילתא\u0004 \u0005[בטעם תלוי הדבר]\u0006 ולנו יש טעם. שאל אותו ר' ירמיה: \u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 זה \u0005מהו]?\u0006 אמר לו ר' אבהו: \u0003זיל לגביה\u0004 \u0005[לך אצל]\u0006 \u0003ר' אבין דאסברתה ניהליה\u0004 \u0005[שהסברתיה לו\u0006 את ההלכה הזו\u0005],\u0006"],["\u0003וכרכיש בה רישיה בי מדרשא\u0004 \u0005[והניד לי בראשו\u0006 כמסכים \u0005בבית המדרש].\u0006 \u0003אזל לגביה\u0004 \u0005[הלך\u0006 ר' ירמיה \u0005אצלו\u0006 אל רבין\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הטעם שנתן ר' אבהו לדבר היה כך: \u0003אילו אמר ליה\u0004 \u0005[היה אומר לו]\u0006 אותו אב לבנו הגדול: \u0003\"קני\u0004 \u0005[קנה]\u0006 \u0003כחמור\" מי קני\u0004 \u0005[האם היה קונה]?\u0006 שכיון שהשווה את קניינו לקנין החמור — לא קנה דבר. ואף כאן, כיון שהשווה את מתנתו למתנה שהוא נותן לבנים שלא נולדו, הרי כשם שהמתנה להם אינה יכולה לחול, כך לא חלה המתנה לבנו הגדול.","ומעירים, דבר זה נאמר גם כהלכה מוסכמת במחלוקת של אמוראים אחרים. \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 האומר לאדם אחר \u0003\"קני\u0004 \u0005[קנה]\u0006 \u0003כחמור\"\u0004 — בוודאי \u0003לא קנה\u0004 כלום, משום שלחמור אין קנין. אבל במקרה שונה, כאשר אמר \u0003\"את\u0004 \u0005[אתה]\u0006 \u0003וחמור\u0004 תקנו את נכסי \u0003\",\u0004 נחלקו בכך, ש\u0003רב נחמן אמר: קנה מחצה,\u0004 את החלק שניתן לו, \u0003ורב המנונא אמר: לא אמר כלום,\u0004 שכיון שצירף אותם בקנין זה, הרי כשם שלא קנה החמור כך לא קנה האיש. \u0003ורב ששת אמר: קנה הכל,\u0004 שנתן הכל לשניהם, וכיון שאין החמור יכול לזכות, נמצא שזכה הוא בכל.","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אני אומר זאת]\u0006 שזכה בכל, ואין להתחשב מה שנאמר לגבי החמור? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: אין לך מר בקישות אלא פנימי שבו,\u0004 שלפעמים החלק הפנימי של הקישות הוא מר ואינו ראוי לאכילה, ואין לתת אותו כתרומה. וכיון שאינו יודע אם הקישות שהוא תורם מר בחלקו הפנימי, \u0003לפיכך כשהוא תורם\u0004 מן הקישות — \u0003מוסיף\u0004 מקישואים אחרים \u0003על החיצון שבו\u0004 שהוא מתוק, \u0003ותורם\u0004 על שאר הקישואים.","ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 חלה התרומה? הרי כמו \u0003\"את\u0004 \u0005[אתה]\u0006 \u0003וחמור\" הוא!\u0004 שהרי החלק הפנימי אינו ראוי לתרומה, ובכל זאת כשהוא נותן מן הפנימי ומן החיצון יחד — יוצא ידי חובה בתרומה שתורם מן החיצון!","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003תרומה מעלייתא\u0004 \u0005[מעולה\u0006 טובה\u0005]\u0006 \u0003היא,\u0004 ורק חכמים אמרו שצריך לחזור ולתרום מן המובחר. ואם כן, אין זה נחשב כצירוף דבר ראוי לתרומה (ולקנין) לדבר שאינו ראוי כלל.","ש\u0003אמר ר' אילעא: מנין לתורם מן הרע על היפה שתרומתו תרומה?\u0004 — \u0003שנאמר: \"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\"\u0004 (במדבר יח, לב), כלומר, לא יהיה בכם חטא אם תרימו תרומה מן החלק הטוב (\"חלבו\"), ומשמע שאם הפריש מן הרע — יש בו משום חטא. \u0003ואם אינו קדוש,\u0004 כלומר, אם אין בהפרשה מן הרע דין תרומה כלל, \u0003נשיאות חטא למה?\u0004 והרי לא עשה מעשה כלל! אלא \u0003מכאן לתורם מן הרע על היפה שתרומתו\u0004 בדיעבד \u0003תרומה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי, מתיב\u0004 \u0005[היה מקשה]\u0006 \u0003רב אויא תיובתא\u0004 \u0005[קושיה]\u0006 על שיטת רב המנונא, ש\"את וחמור\" לא קנה כלום, ממה ששנינו: \u0003מעשה בחמש נשים ובהן\u0004 היו \u0003שתי אחיות, וליקט אחד כלכלה\u0004 (סל) \u0003של תאנים, ושלהן היתה,\u0004 מן השדה שהיה שייך לנשים, \u0003ושל שביעית היתה\u0004 ולכן התאנים היו הפקר, ומה שליקט הרי הוא שלו, \u0003ואמר:\u0004 \u0003\"הרי כולכן מקודשות לי בכלכלה זאת\", וקבלה אחת מהן על ידי\u0004 (עבור) \u0003כולן\u0004 — \u0003אמרו חכמים: אין\u0004 אותן שתי \u0003אחיות מקודשות.\u0004","ויש לדייק: \u0003אחיות הוא\u0004 ש\u0003אין מקודשות, הא\u0004 \u0005[הרי]\u0006 אם היו \u0003נכריות\u0004 (זרות) הנשים האחרות שאינן קרובות זו לזו — \u0003מקודשות. ואמאי\u0004 \u0005[ומדוע]\u0006 יתקדשו האחרות? הלא \u0003\"את וחמור\" היא!\u0004 שהרי הוא מקדש שתי נשים שאינן ראויות לקידושין, ויחד איתן גם נשים הראויות לכך!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לרב מרדכי \u0005:\u0006 \u0003היינו דחזאי\u0004 \u0005[זהו\u0006 ההסבר למה \u0005שראיתי]\u0006 את \u0003רב הונא בר אויא בחלמא\u0004 \u0005[בחלום],\u0006 שמשמעו \u0003דמותיב\u0004 \u0005[\u0006מה \u0005שמקשה]\u0006 \u0003רב אויא תיובתא\u0004 \u0005[קושיה].\u0006 אבל לגופה של הקושיה, \u0003לאו מי אוקימנא\u0004 \u0005[האם לא העמדנו]\u0006 משנה זאת שמדובר שם כש\u0003אמר:\u0004 \u0003\"הראויה מכם לביאה תתקדש לי\"?\u0004 וממילא שתי האחיות לא היו כלל בכלל המקודשות, ואין זה כלל כענין \"את וחמור\".","ובשאלה אחרת הקשורה ללשון של הקנאה משותפת מסופר, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר לה לדביתהו\u0004 \u0005[לאשתו]:\u0006 \u0003\"נכסיי ליך\u0004 \u0005[לך]\u0006 \u0003ולבניך\", אומר רב יוסף: קנתה\u0004 האשה \u0003מחצה\u0004 מן הנכסים כולם, למרות שלא פירש כמה הוא נותן לה. \u0003ואמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אני אומר זאת]?\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אמר:\u0004 נאמר על לחם הפנים, לאחר שמורידים אותו מהשולחן שבמקדש: \u0003\"והיתה לאהרן ולבניו\"\u0004 (ויקרא כד, ט), וכוונתו — \u0003מחצה לאהרן מחצה לבניו,\u0004 ומכאן שאם מפרשים שמו של יחיד עם רבים במתנה, הכוונה היא שהוא מקבל מחצית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: בשלמא התם\u0004 \u0005[נניח שם]\u0006 בענין לחם הפנים, מובן הדבר, שכן \u0003אהרן בר\u0004 \u0005[בן]\u0006 \u0003חלוקה הוא,\u0004 שהוא ראוי מצד עצמו לקבל חלק ככל כהן אחר, \u0003להכי פרט ביה רחמנא למשקל פלגא\u0004 \u0005[לכך פרטה בו התורה\u0006 והזכירה אותו במיוחד, כדי לזכותו יותר, \u0005ליטול מחצה],\u0006 ואולם \u0003אשה לאו\u0004 \u0005[לא]\u0006 \u0003בת ירושה היא\u0004 כלל\u0003,\u0004 ועל כן \u0003דיה שתטול\u0004 חלק בנכסים \u0003כאחד מן הבנים\u0004.","ומקשים על דברי אביי: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא עובדא הוה\u0004 \u0005[והרי מעשה היה\u0006 כעין זה\u0005]\u0006 \u0003בנהרדעא\u0004 שנתן אדם מתנה לפלוני ולאחרים, \u0003ואגביה\u0004 \u0005[והגבה\u0006 ונתן \u0005לו]\u0006 \u0003שמואל פלגא\u0004 \u0005[חצי]!\u0006 וכן היה מעשה כזה \u0003בטבריא, ואגביה\u0004 \u0005[והגבה לו]\u0006 \u0003ר' יוחנן פלגא\u0004 \u0005[חצי]!\u0006 \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק בר יוסף\u0004 מארץ ישראל \u0003אמר: ההוא דמי כלילא דשדו דבי מלכא אאבולי ואאיסטרוגי\u0004 \u0005[אותם דמי כתר,\u0006 סוג של מס, \u0005שהטילו בית הקיסר על חברי מועצת העיר ועל עשיריה],\u0006 \u0003אמר רבי: ניתבו אבולי פלגא ואיסטרוגי פלגא\u0004 \u0005[שיתנו חברי המועצה חצי והעשירים חצי].\u0006 משמע שאם מזכירים שתי קבוצות בהקשר אחד — הכוונה היא שלכל אחת מהן יש מחצית!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם מעיקרא כי הוו כתבי\u0004 \u0005[שם מתחילה כאשר היו כותבים]\u0006 ומטילים מיסים — \u0003אאבולי הוו כתבי\u0004 \u0005[על חברי המועצה היו כותבים\u0006 ומטילים אותם\u0005],\u0006 \u0003ואיסטרוגי הוו מסייעי בהדייהו\u0004 \u0005[ועשירי העיר היו מסייעים בידם],\u0006 \u0003וידע מלכא דהוו קא מסייעי\u0004 \u0005[המלך שהם מסייעים],\u0006 ולכן \u0003השתא מאי דקא כתבי אאבולי ואאיסטרוגי\u0004 \u0005[עכשיו מה שכתבו\u0006 במפורש \u0005על חברי המועצה ועל העשירים]\u0006 הרי זה \u0003למימרא דהני פלגא והני פלגא\u0004 \u0005[לומר שאלה\u0006 נותנים \u0005חצי ואלה חצי].\u0006 ואולם אין ללמוד מכאן שבכל מקום שמזכירים מישהו (או קבוצת אנשים) בנפרד הכוונה היא למחצית.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' זירא\u0004 על רב יוסף ממה ששנינו: \u0003האומר \"הרי עלי מנחה\u0004 של \u0003מאה עשרון\u0004 (עשירית האיפה קמח) \u0003להביא בשני כלים\"\u0004 — \u0003מביא ששים\u0004 עשרון \u0003בכלי אחד, וארבעים\u0004 הנותרים \u0003בכלי אחד,\u0004 שאין מביאים בכלי אחד יותר משישים עשרון."],["\u0003ואם הביא חמשים בכלי אחד וחמשים בכלי אחד\u0004 — \u0003יצא;\u0004 ונדייק מכאן: \u0003אם הביא\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 כלומר, בדיעבד יצא ידי חובתו, \u0003לכתחלה\u0004 — \u0003לא,\u0004 אלא צריך היה להביא ששים בכלי אחד וארבעים בכלי אחר. \u0003ואי סלקא\u0004 \u0005[ואם עולה]\u0006 על \u0003דעתך\u0004 לומר כי \u0003כל כי האי גוונא\u0004 \u0005[כעין זה],\u0006 שמחלק דבר לשנים בלא להגדיר מה יהיה בחלקו של כל אחד, \u0003פלגא ופלגא\u0004 \u0005[מחצה ומחצה]\u0006 \u0003הוא, אפילו לכתחלה נמי\u0004 \u0005[גם כן]\u0006 יביא חמישים וחמישים!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם אנן סהדי דהאי גברא מעיקרא\u0004 \u0005[שם,\u0006 בענין המנחה, \u0005אנו עדים,\u0006 הכל מבינים, \u0005שאותו אדם מתחילה]\u0006 \u0003לקרבן גדול קא מכוין\u0004 \u0005[מתכוון],\u0006 \u0003והאי דקאמר\u0004 \u0005[וזה שהוא אומר]\u0006 \u0003בשני כלים\u0004 — משום \u0003דידע\u0004 \u0005[ש\u0006הוא \u0005יודע]\u0006 ש\u0003לא אפשר לאתויי\u0004 \u0005[להביא]\u0006 את כולם \u0003בכלי אחד,\u0004 ולכן \u0003כמה\u0004 ש\u0003אפשר לאיתויי\u0004 \u0005[להביא]\u0006 בכלי אחד \u0003מייתינן\u0004 \u0005[מביאים],\u0006 ובכלי אחד לא ניתן להביא יותר מששים. אבל בכל מקרה אחר בו אין הנחה מוקדמת כזאת, מחלקים את הדבר לשני חלקים שווים.","ובמסקנת ההלכה מעירים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב יוסף\u0004 במחלוקתו נגד רבה, בשלושה עניינים: \u0003בשדה\u0004 (ב\"ב יב,ב) ב\u0003ענין\u0004 (ב\"ב קיד,א), \u0003ו\u0004ב\u0003מחצה,\u0004 כלומר, בענייננו, שאם נתן וחילק לשתי קבוצות ולא פירש כמה, הרי זה מחצה לכל קבוצה.","ובענין דומה הנוגע למתנה שלא נאמרה בה חלוקה ברורה, מסופר, \u0003ההוא דשדר פיסקי דשיראי לביתיה\u0004 \u0005[\u0006אדם \u0005אחד שלח חתיכות משי לביתו]\u0006 במתנה. \u0003אמר ר' אמי: הראויין ל\u0004בגדי \u0003בנים\u0004 — ניתנים \u0003לבנים,\u0004 ה\u0003ראויין לבנות\u0004 — ניתנים \u0003לבנות.\u0004 ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא דלית ליה כלתא\u0004 \u0005[\u0006כ\u0005שאין לו כלות],\u0006 \u0003אבל\u0004 אם \u0003אית ליה כלתא\u0004 \u0005[יש לו כלות]\u0006 — \u0003לכלתיה שדר\u0004 \u0005[לכלותיו שלח].\u0006 \u0003ואי בנתיה לא נסיבן\u0004 \u0005[ואם בנותיו אינן נשואות],\u0006 \u0003לא שבק בנתיה ומשדר לכלתיה\u0004 \u0005[אינו מניח\u0006 את \u0005בנותיו ושולח לכלותיו].\u0006","מסופר, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 בצוואה: \u0003נכסיי לבניי. הוה ליה ברא וברתא\u0004 \u0005[היו לו בן ובת],\u0006 והשאלה היתה: \u0003מי קרו אינשי לברא בניי\u0004 \u0005[האם קוראים אנשים לבן\u0006 אחד \u0005בני],\u0006 \u0003ולסלוקי לברתא\u0004 \u0005[ולסלק את הבת]\u0006 \u0003מעישור\u0004 נכסים \u0003קאתי\u0004 \u0005[הוא בא],\u0006 כלומר, שלא תקבל אף עישור נכסים לנדוניה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא קרו אינשי לברא בניי\u0004 \u0005[אין קוראים אנשים לבן\u0006 אחד \u0005בני],\u0006 \u0003ולמושכה לברתא\u0004 \u0005[ולצרף את בתו]\u0006 \u0003במתנה קאתי\u0004 \u0005[הוא בא]?\u0006","\u0003אמר אביי, תא שמע\u0004 \u0005[בוא ושמע]\u0006 שנאמר: \u0003\"ובני דן חשים\"\u0004 (בראשית מו, כג), ולא נזכר בן נוסף, משמע שאף לבן אחד קורים \"בנים\". \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: דלמא כדתנא דבי\u0004 \u0005[שמא\u0006 יש לפרש פסוק זה \u0005כמו ששנה\u0006 החכם \u0005בבית]\u0006 מדרשו של \u0003חזקיה,\u0004 שאין \"חושים\" שמו של בנו של דן, אלא לומר \u0003שהיו\u0004 בניו \u0003מרובין כחושים\u0004 (קבוצות) \u0003של קנה,\u0004 ולכן השתמשו בלשון רבים! \u0003אלא אמר רבא:\u0004 ראיה היא ממה שנאמר: \u0003\"ובני פלוא אליאב\"\u0004 (במדבר כו, ח), למרות שנזכר רק בן אחד. \u0003רב יוסף אמר,\u0004 ראיה היא ממה שנאמר: \u0003\"ובני איתן עזריה\"\u0004 (דברי הימים א ב, ח).","מסופר, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם\u0006 בצוואה\u0005]:\u0006 \u0003\"נכסאי לבנאי\"\u0004 \u0005[נכסיי לבני],\u0006 \u0003הוה ליה ברא ובר ברא\u0004 \u0005[היה לו בן ובן הבן],\u0006 והשאלה היתה: האם \u0003קרו אינשי לבר ברא \"ברא\"\u0004 \u0005[קוראים אנשים לבן הבן \"בן\"]\u0006 \u0003או לא? רב חביבא אמר: קרו אינשי לבר ברא \"ברא\"\u0004 \u0005[קוראים אנשים לבן הבן \"בן\"],\u0006 \u0003מר בר רב אשי אמר: לא קרו אינשי לבר ברא \"ברא\"\u0004 \u0005[אין קוראים אנשים לבן הבן \"בן\"].\u0006 ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003מר בר רב אשי: המודר הנאה מבנים\u0004 של אדם מסויים — \u0003מותר בבני בנים,\u0004 משמע שאינם בכלל בנים.","אדם שמת ו\u0003הניח בנים גדולים וקטנים,\u0004 אם \u0003השביחו גדולים את הנכסים\u0004 — \u0003השביחו לאמצע,\u0004 כלומר, כאשר מחלקים את הירושה, מחלקים גם את השבח בין כולם. אבל \u0003אם אמרו\u0004 הבנים הגדולים מתחילה: \u0003ראו מה שהניח אבא הרי אנו עושין\u0004 מלאכה בנכסים \u0003ואוכלים\u0004 מה שעשינו — מה ש\u0003השביחו\u0004 הוא \u0003לעצמן. וכן האשה שהשביחה את הנכסים\u0004 — \u0003השביחה לאמצע.\u0004 ו\u0003אם אמרה: \"ראו מה שהניח לי בעלי, הרי אני עושה ואוכלת\"\u0004 — הרי \u0003השביחה לעצמה.\u0004","על מה שנאמר במשנה, שאם השביחו הגדולים את הנכסים, השביחו לאמצע, \u0003אמר רב חביבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לא שנו אלא ששבחו\u0004 ה\u0003נכסים מחמת נכסים,\u0004 שהיורשים הללו הוציאו כסף מן הנחלה המשותפת כדי להשביח את הנכסים, ועבודתם היתה רק בניהול ההשקעות, \u0003אבל\u0004 אם \u0003שבחו\u0004 ה\u0003נכסים מחמת עצמן,\u0004 כלומר, מחמת עבודתם או ממונם של הבנים הגדולים — בכל מקרה \u0003השביחו לעצמן.\u0004","ושואלים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' חנינא: אפילו לא הניח להם אביהם אלא\u0004"],["\u0003אודייני\u0004 (מכתשת) שמשתמשים בה אחרים תמורת תשלום, \u0003השכר\u0004 שמקבלים עליה הוא \u0003לאמצע; והא\u0004 \u0005[והרי]\u0006 \u0003אודייני\u0004 שהרווח שלה \u0003מחמת עצמו הוא,\u0004 שהגדולים צריכים לעמוד ולשמור ולהשגיח על עבודתה, ואין כאן הוצאות על חשבון הנכסים, ובכל זאת אנו אומרים שכולם מתחלקים בשווה! ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003אודייני, דלנטירותא\u0004 \u0005[שלשמירה]\u0006 \u0003הוא דעבידא\u0004 \u0005[שעשויה]\u0006, \u0003ואפילו קטנים נמי מצו מנטרי לה\u0004 \u0005[גם כן יכולים לשמור אותה],\u0006 ובמקרה כזה אין לגדולים יתרון על הקטנים אשר בגללו יכולים הם לדרוש לעצמם יותר משותפים רגילים.","שנינו במשנה שאם \u0003אמרו\u0004 האחים הגדולים \u0003\"ראו מה שהניח אבא הרי אנו עושין ואוכלין\"\u0004 — \u0003השביחו לעצמן.\u0004 מסופר: \u0003רב ספרא שבק אבוה זוזי\u0004 \u0005[הניח אביו\u0006 \u0005זוזים,\u0006 דינרים\u0005].\u0006 \u0003שקלינהו עבד בהו עיסקא\u0004 \u0005[נטל אותם\u0006 רב ספרא \u0005עשה בהם עסק].\u0006 \u0003אתו אחי תבעוהו בדינא קמיה\u0004 \u0005[באו האחים\u0006 ו\u0005תבעו אותו לדין לפני]\u0006 \u0003רבא\u0004 שיתן גם להם מן הרווחים, \u0003אמר להו\u0004 \u0005[להם]\u0006 רבא: \u0003רב ספרא גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003הוא, לא שביק גירסיה וטרח לאחריני\u0004 \u0005[אינו מניח\u0006 את \u0005לימודו\u0006 כדי \u0005לטרוח לאחרים]\u0006 ולכן ברור שאם טרח — טרח לעצמו, למרות שלא התנה כן במפורש.","שנינו במשנה: \u0003האשה שהשביחה את הנכסים\u0004 — \u0003השביחה לאמצע.\u0004 ושואלים: \u0003אשה בנכסי יתמי\u0004 \u0005[יתומים]\u0006 \u0003מאי עבידתה\u0004 \u0005[מה מעשיה]?\u0006 כלומר, מה עניינה ומה זכותה בנכסים הללו? \u0003אמר ר' ירמיה:\u0004 כאן מדובר \u0003באשה יורשת,\u0004 כגון שהיתה בת אחיו של בעלה, וכשמת בלא בנים — ירשה אותו במקום אביה (שמת גם הוא בלא בנים).","ואומרים: אם כך, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, שדינה כשאר יורשים! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דלאו\u0004 \u0005[שאין]\u0006 \u0003דרכה\u0004 של אשה \u0003למטרח\u0004 \u0005[לטרוח]\u0006 בהשבחה של נכסים, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא פריש\u0004 \u0005[פירשה]\u0006 שלעצמה היא עושה — \u0003כמו דפריש דמי\u0004 \u0005[שפירשה נחשב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שדווקא אם פירשה הרווחים לעצמה.","שנינו במשנה ש\u0003אם אמרה \"ראו מה שהניח לי בעלי הריני עושה ואוכלת\"\u0004 — \u0003השביחה לעצמה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שכך הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דשביחא לה מילתא\u0004 \u0005[שמשובח עבורה הדבר],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006כן שומעת היא \u0005שאנשים\u0006 \u0005אומרים]:\u0006 ראו עד כמה \u0003קא טרחא קמי יתמי\u0004 \u0005[היא טורחת לפני היתומים]\u0006 — \u0003אחולי אחלה\u0004 \u0005[\u0006הרי היא \u0005מוחלת\u0006 על השבח\u0005],\u0006 וחולקת עמם בשווה \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא.","\u0003אמר ר' חנינא: המשיא אשה לבנו גדול בבית\u0004 שייחד לצורך החופה ומשתה הנישואין — \u0003קנאו\u0004 הבן את הבית במתנה. ומוסיפים: \u0003ודוקא\u0004 כשהיה זה בנו ה\u0003גדול, ודוקא\u0004 שמשיאו \u0003בתולה, ודוקא\u0004 שהיא \u0003אשתו ראשונה\u0004 של הבן, \u0003ודוקא שהשיאו ראשון\u0004 בין בניו, שאז יש לומר שמתוך כל הטעמים האלה חביב עליו ביותר ונתן לו.","ומבררים פרטי דברים בענין זה: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 שאם \u0003ייחד לו אביו בית\u0004 לנישואין \u0003ו\u0004יש \u0003עלייה\u0004 על גבי הבית — את ה\u0003בית קנה,\u0004 את ה\u0003עלייה לא קנה;\u0004 אלא יש לשאול: אם ייחד לו \u0003בית\u0004 לנישואין \u0003ו\u0004יש \u0003אכסדרה\u0004 (כמין חדר כניסה שלפני הבית) לאותו בית, ועשה את הנישואין בבית, \u0003מהו\u0004 הדין? האם נתן לו גם את האכסדרה? וכן \u0003שני בתים זה לפנים מזה,\u0004 וייחד את הפנימי לנישואין, \u0003מהו?\u0004 שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003ייחד לו אביו בית וכלי בית\u0004 לנישואיו — \u0003כלי בית קנה, בית לא קנה! אמר ר' ירמיה: כגון שהיה אוצרו\u0004 (מחסנו) \u0003של אביו מונח שם,\u0004 שכיון שברור שלא הקנה לו את האוצר אף לא הקנה לו את הבית. \u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעא אומרים]:\u0006 \u0003אפילו\u0004 היה שם \u0003שובכא דיוני\u0004 \u0005[שובך יונים]\u0006 של האב, לא הקנה לו את הבית. \u0003רב יהודה ורב פפי אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אפילו\u0004 היה שם \u0003עציצא\u0004 \u0005[עציץ,\u0006 כלי\u0005]\u0006 של האב המכיל \u0003הרסנא\u0004 \u0005[דגים מטוגנים]\u0006 הרי זה מראה שהאב שומר את רכושו לעצמו. ומסופר: \u0003מר זוטרא אנסביה לבריה, ותלא ליה סנדלא\u0004 \u0005[השיא את בנו בבית, ותלה בו סנדל]\u0006 להודיע שהוא שומר לעצמו את זכות הקנין בבית. \u0003רב אשי נסביה לבריה, ותלא ליה אשישא דמשחא\u0004 \u0005[השיא את בנו, ותלה לו כלי של שמן\u0006 לצורך זה\u0005].\u0006","\u0003אמר מר זוטרא, הני תלת מילי שוינהו רבנן כהלכתא בלא טעמא\u0004 \u0005[שלושה דברים אלה עשו אותם חכמים כהלכה\u0006 קבועה \u0005בלי טעם\u0006 מספיק\u0005]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003הא\u0004 \u0005[זו],\u0006 \u0003אידך\u0004 \u0005[האחרת]\u0006 — מה ש\u0003אמר רב יהודה אמר שמואל: הכותב כל נכסיו לאשתו\u0004 — \u0003לא עשאה אלא אפוטרופא\u0004 \u0005[אפוטרופוסית]\u0006 לנכסים, ולא נתן לה דבר. \u0003אידך\u0004 \u0005[האחרת]\u0006 — ש\u0003אמר רב:\u0004 האומר לחבירו \u0003\"\u0004אותו \u0003מנה\u0004 שיש \u0003לי בידך,\u0004 שאתה חייב לי, \u0003תנהו לפלוני\",\u0004 אם היה הדבר \u0003במעמד שלשתן\u0004 — \u0003קנה\u0004 השלישי, ואין צורך במעשה קנין ובעדים. ושלושה דינים אלה אין לנו טעם ברור מדוע נקבעו."],["\u0003אחין השותפין שנפל אחד מהן לאומנות,\u0004 כלומר, לקחו אותו לעבודת כפייה עבור המלך — הרי זה \u0003נפל לאמצע,\u0004 כלומר, כל האחים מתחלקים בהוצאות, או ברווח. אבל אם \u0003חלה ונתרפא,\u0004 והוציא הוצאות לשם כך — \u0003נתרפא משל עצמו.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003אומנות\u0004 שהזכרנו — הכוונה \u0003לאומנות המלך,\u0004 ולא שיצא לעסוק במלאכה לעצמו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד מן האחין שמינוהו גבאי\u0004 עבור המלוכה, \u0003או פולמוסטוס\u0004 (ממונה על אנשי צבא), ועל ידי כך הוא מרוויח כסף, \u0003אם מחמת האחין,\u0004 כלומר, שמכל משפחה היו לוקחים אדם אחד לצורך זה — הרי כל מה שמרוויח ניתן \u0003ל\u0004כל ה\u0003אחין, אם מחמת עצמו\u0004 לקחו אותו — הרי זה \u0003לעצמו.\u0004","ומבררים: \u0003אם מחמת אחין\u0004 — \u0003לאחין, פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה שהוא היה \u0003חריף טפי\u0004 \u0005[יותר]\u0006 מהאחרים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003חורפיה גרים ליה\u0004 \u0005[חריפותו גרמה לו]\u0006 ומשום כך נבחר לתפקיד זה. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלמרות זאת, הואיל ונלקח כנציג המשפחה — השכר לאמצע.","ועוד בענין משנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד מן האחין שנטל מאתים זוז\u0004 מן הירושה, כדי ליזון מהם בזמן שהוא הולך למקום אחר \u0003ללמוד תורה או ללמוד אומנות\u0004 (מלאכה), \u0003יכולין\u0004 שאר \u0003האחין לומר לו: \"\u0004אינך רשאי, אלא \u0003אם אתה אצלנו\u0004 — \u0003יש לך מזונות\u0004 כאחד מאיתנו. \u0003אם אין אתה אצלנו\u0004 — \u0003אין לך מזונות\".\u0004 ושואלים: ומדוע?","\u0003וליתבו ליה\u0004 \u0005[ושיתנו לו]\u0006 ב\u0003כל היכא דאיתיה\u0004 \u0005[מקום שישנו]\u0006 מה שהוא צריך! ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב הונא,\u0004 ש\u0003אמר רב הונא: ברכת הבית ברובה,\u0004 שכאשר יש אנשים מרובים בבית, ההוצאות עבור כל אחד מבני הבית קטנות יותר. ונמצא שהוא מוציא הוצאות רבות יותר כשהוא מחוץ לבית. ושואלים: \u0003וליתבו ליה\u0004 \u0005[ושיתנו לו]\u0006 \u0003לפי ברכת הבית,\u0004 שלא יתנו לו את כל מה שהוא צריך, אלא מה שהיו הוצאותיו כאילו היה בתוך הבית! ומשיבים: \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 הוא, שכך צריכים לתת לו.","שנינו במשנה שאם \u0003חלה ונתרפא\u0004 — \u0003נתרפא משל עצמו. שלח רבין\u0004 מארץ ישראל לבבל \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אלעא: לא שנו\u0004 דבר זה \u0003אלא שחלה בפשיעה\u0004 על ידי רשלנותו שלו, \u0003אבל\u0004 אם חלה \u0003באונס\u0004 — \u0003נתרפא מן האמצע.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 הענין הזה שאדם חולה \u0003בפשיעה?\u0004 ומשיבים: \u0003כ\u0004מו שאמר \u0003ר' חנינא,\u0004 ש\u0003אמר ר' חנינא: הכל,\u0004 כל המאורעות באים על אדם, \u0003בידי שמים, חוץ מצנים פחים,\u0004 כלומר, קור ומכשולים, שאדם יכול להיזהר בהם, \u0003שנאמר: \"צנים פחים בדרך עקש שומר נפשו ירחק מהם\"\u0004 (משלי כב, ה).","\u0003האחין שעשו מקצתן שושבינות בחיי האב,\u0004 כלומר, שאביהם שלח בידיהם מתנות וצרכי סעודה לנישואיו של חבירו. והמנהג היה שכאשר נישא אחד מן האחים, היו שולחים מן המשפחה האחרת שושבין עם מתנות בערך לא פחות ממה שקיבלו הם. כאשר \u0003חזרה שושבינות,\u0004 כלומר, כאשר לאחר מות האב נישא אחד מהאחים, ובני המשפחה האחרת שלחו מתנות כשושבינות — \u0003חזרה לאמצע\u0004 ולא רק לאותו אח שושבין. וטעם הדבר, לפי \u0003שהשושבינות נגבית בבית דין,\u0004 כלומר, שהיא נחשבת כחוב לכל דבר, שהיו חייבים לאב, והיו גובים אותה אפילו בבית דין. \u0003אבל השולח לחבירו כדי יין וכדי שמן\u0004 כמתנה לחתונה — \u0003אין נגבין בבית דין, מפני שהן\u0004 בגדר \u0003גמילות חסדים.\u0004","שנינו במשנה שהשולח שושבינות עם בנו — הריהי חוזרת לאמצע. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003שלח לו אביו שושבינות, כשהיא חוזרת\u0004 — \u0003חוזרת לו.\u0004 ואם \u0003נשתלחה לאביו שושבינות, כשהיא חוזרת\u0004 כשהמשפחה צריכה להחזיר — \u0003חוזרת מן האמצע.\u0004 הרי שדינה הראשון של הברייתא חולק על דין המשנה! \u0003אמר ר' אסי אמר ר' יוחנן: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן\u0006 ב\u0005משנתנו]\u0006 שחזרה שושבינות לאמצע, במקרה ש\u0003נשתלחה\u0004 השושבינות \u0003לאביו תנן\u0004 \u0005[שנינו],\u0006 כלומר, לנישואי אחד מבניו.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אחין שעשו מקצתן שושבינות\" קתני\u0004 \u0005[שנה],\u0006 משמע שלא האב קיבל מתנות, אלא האחים שלחו שושבינות לאחרים! ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן: \"שעשו \u0003למקצתן\u0004 שושבינות\". ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"חזרה שושבינות\" קתני\u0004 \u0005[שנה]\u0006 ומשמע: חזרה למשפחה זו! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם \u0003חזרה\u0004 השושבינות \u0003לגבות\u0004 (להיגבות), שצריך להחזיר אותה — הריהי \u0003נגבית מאמצע.\u0004","\u0003ר' אסי אמר:\u0004 גם אם נפרש את משנתנו כפשוטה — \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 במשנה, מדובר שהאב שלח את השושבינות \u0003בסתם. כאן\u0004 בברייתא, מדובר \u0003במפרש,\u0004 כשהשושבינות נשלחת על שמו של הבן השליח\u0003. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שלח לו\u0004 (עבורו) \u0003אביו שושבינות, כשהיא חוזרת\u0004 — \u0003חוזרת לו\u0004 לאותו בן, \u0003שלח אביו שושבינות סתם, כשהיא חוזרת\u0004 — \u0003חוזרת לאמצע. ו\u0004אילו","\u0003שמואל אמר:\u0004 גם אם נפרש את משנתנו במפרש, \u0003הכא\u0004 \u0005[כאן]\u0006 במשנה, שחזרה השושבינות לאמצע, \u0003ביבם עסקינן\u0004 \u0005[אנו עוסקים],\u0006 כאשר מת הבן השושבין בלא בנים, ואחיו יבם את אשתו, ובחתונת היבם נשלחה לו השושבינות. ועל כך נאמר שאין הוא לבדו מקבלה, אלא היא מתחלקת בין האחים. שאף שיבם יורש את אחיו, מכל מקום \u0003אינו נוטל ב\u0004מה ש\u0003ראוי\u0004 לבוא לידי אחיו \u0003כ\u0004מו \u0003ב\u0004מה שכבר היה \u0003מוחזק\u0004 בידי האח.","ושואלים: \u0003מכלל\u0004 הדברים אתה שומע \u0003דאידך\u0004 \u0005[שהאחר]\u0006 שנשלחה לו השושבינות על ידי האח שמת, \u0003משלם?\u0004 \u0003לימא\u0004 \u0005[שיאמר]:\u0006 \u0003\"תנו לי שושביני ואשמח עמו\",\u0004 ומכיון ששושבינו אינו נמצא, אינו חייב בכך!","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 בענין דומה \u0005:\u0006 \u0003מקום שנהגו להחזיר\u0004 כסף \u0003קדושין\u0004 כאשר מת הארוס או הארוסה — \u0003מחזירין, מקום שנהגו שלא להחזיר\u0004 — \u0003אין מחזירין. ואמר רב יוסף בר אבא אמר מר עוקבא אמר שמואל: לא שנו\u0004 כן \u0003אלא\u0004 באופן \u0003שמתה היא,\u0004 שאז הולכים אחר המנהג, \u0003אבל מת הוא\u0004 — לכל הדעות \u0003אין מחזירין\u0004 למשפחתו, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003יכולה היא שתאמר:\u0004"],["\u0003\"תנו לי בעלי ואשמח עמו\",\u0004 כלומר, אני מוכנה להשלים את התנאי מצידי, ואין העיכוב תלוי בי, \u0003הכא נמי נימא\u0004 \u0005[כאן גם כן שיאמר]:\u0006 \u0003\"תנו לי שושביני ואשמח עמו\"!\u0004","\u0003אמר רב יוסף: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון ש\u0004האח שמת \u0003שמח עמו שבעה ימי משתה, ולא הספיק לפורעו עד שמת.\u0004 ונמצא שאינו יכול לטעון דבר, שהרי שמח עם שושבינו. ומכל מקום, כאמור, אין היבם (הבא במקומו) זכאי לקבל את השושבינות לעצמו בלבד, והיא חוזרת לאמצע.","ומבררים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי הנימוק הזה של \u0003\"תנו לי בעלי ואשמח עמו\" תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא?\u0004 ומהי אותה מחלוקת? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המארס את האשה\u0004 ובטלו האירוסין, אם היתה \u0003בתולה\u0004 — \u0003גובה מאתים\u0004 דינרים בכתובתה, \u0003ואלמנה\u0004 — גובה \u0003מנה\u0004 (מאה דינרים). \u0003מקום שנהגו להחזיר קדושין\u0004 — \u0003מחזירין, מקום שנהגו שלא להחזיר קדושין\u0004 — \u0003אין מחזירין,\u0004 אלו \u0003דברי ר' נתן. ר' יהודה הנשיא אומר, באמת אמרו: מקום שנהגו להחזיר\u0004 — \u0003מחזירין, מקום שנהגו שלא להחזיר\u0004 — \u0003אין מחזירין.\u0004","ותחילה תוהים: שיטת \u0003ר' יהודה הנשיא היינו\u0004 \u0005[הרי זו]\u0006 בדיוק שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון,\u0006 ר' נתן\u0005]\u0006 ומה מוסיף הוא בדבריו?! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 בנימוק של \u0003\"תנו לי בעלי ואשמח עמו\" איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל,","\u0003וחסורי מחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 הברייתא \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003המארס את האשה,\u0004 אם היתה \u0003בתולה\u0004 — \u0003גובה מאתים, ואלמנה\u0004 — \u0003מנה. במה דברים אמורים\u0004 — \u0003דהדר ביה איהו\u0004 \u0005[שחזר בו הוא].\u0006 \u0003אבל\u0004 אם \u0003מתה\u0004 האשה, \u0003מקום שנהגו להחזיר\u0004 — \u0003מחזירין, מקום שנהגו שלא להחזיר\u0004 — \u0003אין מחזירין. ודוקא שמתה היא, אבל מת הוא\u0004 — \u0003אין מחזירין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003יכולה היא שתאמר: \"תנו לי בעלי ואשמח עמו\",\u0004 אלו דברי ר' נתן.","\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יהודה הנשיא למימר\u0004 \u0005[לומר],\u0006 \u0003באמת אמרו: בין מת הוא ובין מתה היא, מקום שנהגו להחזיר\u0004 — \u0003מחזירין, מקום שנהגו שלא להחזיר\u0004 — \u0003אין מחזירין, ולא מציא אמרה\u0004 \u0005[יכולה לומר]:\u0006 \u0003\"תנו לי בעלי ואשמח עמו\"!\u0004","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003יכולה\u0004 האשה \u0003שתאמר: \"תנו לי בעלי ואשמח עמו\". ודמית\u0004 \u0005[וכאשר מת]\u0006 \u0003הוא כולי עלמא\u0004 \u0003לא פליגי\u0004 \u0005[והכל אינם חולקים]\u0006 שאין מחזירים את הקידושין. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הוא במקרה \u0003שמתה היא, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה של \u0003קדושין לטיבועין ניתנו קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 כלומר, האם הקידושין ניתנו לצמיתות, כאילו לטבוע בידי האשה, אף על פי שלא התקיימו הנישואין, או שמא הם מוחזרים, ש\u0003ר' נתן סבר\u0004 \u0005[סבור]:\u0006 \u0003קדושין לאו\u0004 \u0005[לא]\u0006 \u0003לטיבועין ניתנו,\u0004 ולכן הדברים תלויים במנהג, ואם נהגו להחזיר — מחזירים, \u0003ור' יהודה הנשיא סבר\u0004 \u0005[סבור]:\u0006 \u0003קדושין לטיבועין ניתנו.\u0004 ותוהים: כיצד יכול אתה לפרש כך?","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מקום שנהגו להחזיר מחזירין\" קתני\u0004 \u0005[שנה]\u0006 בדברי ר' יהודה הנשיא! ומשיבים: דברים אלו אינם אמורים בקידושין, שאלו אינם חוזרים בכל מקרה, אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003וסבלונות,\u0004 מתנות שנתן החתן לכלה אחר האירוסין, \u0003ודאי מקום שנהגו להחזיר\u0004 — \u0003מחזירין.\u0004","ומעירים: \u0003והני תנאי כהני תנאי\u0004 \u0005[ותנאים אלה\u0006 שלהלן נחלקו \u0005כתנאים אלה\u0006 הקודמים\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קדשה\u0004 את האשה \u0003בככר\u0004 של כסף, שהוא סכום גדול (ששת אלפי דינרים) — \u0003בתולה גובה\u0004 בכתובתה \u0003מאתים\u0004 בנוסף לכסף קידושיה זה, \u0003ואלמנה מנה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: בתולה גובה מאתים, ואלמנה מנה, ומחזרת לו את השאר,\u0004 את כסף הקידושין. \u0003ר' יוסי אומר:\u0004 אם \u0003קדשה בעשרים\u0004 — \u0003נותן לה שלשים חצאין,\u0004 אם \u0003קדשה בשלשים\u0004 — \u0003נותן\u0004 \u0003לה עשרים חצאין,\u0004 כמבואר להלן.","ונברר: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שעוסקים במקרה \u0003שמתה\u0004 האשה, \u0003מי אית\u0004 \u0005[האם יש]\u0006 \u0003לה כתובה? ואלא,\u0004 יש לפרש שמדובר \u0003שמת הוא,\u0004 ואם כן, יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 לדעת ר' יהודה \u0003מחזרת לו את השאר,\u0004 כלומר, את כסף הקידושין? \u0003ונימא\u0004 \u0005[ונאמר]\u0006 שיכולה היא לטעון: \u0003\"תנו לי בעלי ואשמח עמו\"! ואלא\u0004 יש לפרש שמדובר כאן \u0003באשת ישראל שזינתה,\u0004 שאינה יכולה לטעון כך משום שהיא אסרה עצמה עליו. ונברר: \u0003ובמאי\u0004 \u0005[ו\u0006אולם יש לשאול \u0005במה\u0006 דברים אמורים\u0005],\u0006 באיזה מקרה מדובר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ברצון\u0004 זינתה, \u0003מי אית\u0004 \u0005[האם יש]\u0006 \u0003לה כתובה\u0004 כלל? \u0003ואלא\u0004 תאמר שזינתה \u0003באונס,\u0004 והלא \u0003מישרא שריא ליה\u0004 \u0005[מותרת\u0006 היא \u0005לו]\u0006 ומדוע תחזיר לו את דמי הקידושין?","\u0003ואלא,\u0004 צריכים לומר שמדובר כאן \u0003באשת כהן שנאנסה\u0004 שהיא אסורה עליו, שמצד אחד זכאית היא לכתובתה, אבל מצד אחר, לגבי כסף הקידושין אינה יכולה לטעון \"תנו לי בעלי ואשמח עמו\", שהרי היא עצמה נאסרה. \u0003ו\u0004אם כן בשאלה האם \u0003בקדושין לטיבועין ניתנו קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003קדושין לטיבועין ניתנו\u0004 וכסף הקידושין לעולם אינו חוזר, \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 קידושין \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לטיבועין ניתנו,\u0004 ולפיכך היא מחזירה את דמי הקידושין. \u0003ור' יוסי מספקא ליה\u0004 \u0005[מסופק היה לו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לטיבועין ניתנו אי\u0004 \u0005[או]\u0006 \u0003לא,\u0004","\u0003והלכך\u0004 \u0005[ועל כן]\u0006 מפני הספק, היא מחזירה לו מחצית מכסף הקידושין. ולכן אם \u0003קדשה בעשרים\u0004 סלעים (שהם שמונים דינרים) היא חייבת לו ארבעים דינרים. אלא שמצד אחר, אם היתה זו אלמנה, הריהי זכאית לכתובתה בסך מאה דינרים, ולכן הוא \u0003נותן לה שלשים חצאין\u0004 (חצאי סלעים) שהם ששים דינרים, ונמצא כל שבידה מאה. אם \u0003קדשה בשלשים\u0004 סלעים (שהם מאה ועשרים דינר) והיא מחזירה מחציתם, דהיינו שישים, ומצד אחר היא זכאית למאה דינרים בכתובתה — \u0003נותן לה עשרים חצאין\u0004 שהם ארבעים דינר.","\u0003אמר רב יוסף בר מניומי אמר רב נחמן: בכל מקום שנהגו להחזיר\u0004 את כסף הקידושין — \u0003מחזירין. ותרגומא\u0004 \u0005[ותרגומו,\u0006 פירושו של הדבר\u0005]:\u0006 שמדובר במנהג ב\u0003נהרדעא.\u0004 ושואלים: \u0003שאר בבל מאי\u0004 \u0005[מה\u0006 דינה\u0005]?\u0006 \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מוהרי הדרי, קדושי לא הדרי\u0004 \u0005[המוהר חוזר, הקידושין אינם חוזרים].\u0006 \u0003אמר רב פפא, הלכתא\u0004 \u0005[הלכה\u0006 פסוקה\u0005]\u0006 היא כך \u0005:\u0006 \u0003בין שמת הוא, בין שמתה היא,\u0004 אם \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003הוא\u0004 — \u0003מוהרי הדרי, קדושי לא הדרי\u0004 \u0005[המוהר חוזר, הקידושין אינם חוזרים];\u0006 \u0003הדרא בה איהי\u0004 \u0005[חזרה בה היא]\u0006 — \u0003אפילו קדושי נמי הדרי\u0004 \u0005[\u0006\u0005הקידושין גם כן חוזרים].\u0006","\u0003אמימר אמר: קדושי לא הדרי\u0004 \u0005[\u0006\u0005הקידושין אינם חוזרים],\u0006 \u0003גזירה שמא יאמרו קדושין תופסין באחותה,\u0004 שיחשבו אנשים שהקידושין הללו בטלו מעיקרם, וכאילו לא קידשה, ואותו אדם רשאי אחר כך לקדש את אחותה. ולא היא, שכיון שכבר קידש את האחות האחת — אינו יכול לקדש את השניה. \u0003רב אשי אמר: גיטה מוכיח עליה\u0004 שהיא גרושה, ולכן יודעים הכל שאינו רשאי לשאת את אחותה. ומעירים: \u0003והא\u0004 \u0005[וזו]\u0006 של \u0003רב אשי בדותא היא\u0004 \u0005[דבר שאינו נכון הוא],\u0006 שאי אפשר לסמוך על מה שנתנו לה גט, \u0003דאיכא\u0004 \u0005[שיש]\u0006 ש\u0003שמע בהא\u0004 \u0005[בזו,\u0006 בהחזרת הקידושין\u0005]\u0006 \u0003ולא שמע בהא\u0004 \u0005[בזו,\u0006 בגט\u0005],\u0006 ויבואו לטעות.","שנינו במשנה: \u0003שהשושבינות נגבית בבית דין. תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003חמשה דברים נאמרו בשושבינות: נגבית בבית דין\u0004 שהיא כחוב גמור. \u0003וחוזרת בעונתה,\u0004 כלומר, אין מחזירים אותה, אלא דווקא בזמן נישואין. \u0003ואין בה משום רבית\u0004 אם כשמחזיר הוא מוסיף יותר על מה שקיבל."],["\u0003ואין השביעית\u0004 (שנת השמיטה) \u0003משמטתה\u0004 ככל מילוה. כלומר, גם אם הגיעה שנת השמיטה לפני שנשא חבירו אשה, אין חוב זה נשמט, והוא חייב לפורעו כשיישא חבירו אשה. \u0003ואין הבכור נוטל בה פי שנים\u0004 אם מת השושבין, וחבירו מחזיר את השושבינות למשפחה בנישואי אחד הבנים.","ומעתה מבארים את דברי הברייתא: \u0003נגבית בבית דין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 משום ש\u0003כמלוה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת].\u0006 \u0003ואין בה משום רבית\u0004 — משום \u0003דלאו אדעתא דהכי יהב ליה\u0004 \u0005[שלא על דעת כן נתן לו]\u0006 את התוספת, אלא מחמת שמחה וידידות, ואין כאן ענין של הלוואה בריבית. \u0003ואין השביעית משמטתה\u0004 — משום \u0003דלא קרינא ביה\u0004 \u0005[שאין אנו קוראים בו],\u0006 מה שנאמר בענין זה: \u0003\"לא יגש\u0004 (ילחץ) את רעהו...","כי קרא שמיטה לה'\u0003\"\u0004 (דברים טו, ב). שהרי אינו יכול לומר לו בשנת השמיטה: החזר לי את כספי, לפי שרק כשמגיע זמן הנישואין עליו להחזיר, ולא קודם לכן. \u0003ואין הבכור נוטל פי שנים\u0004 — \u0003דהוה ליה\u0004 \u0005[שהרי זה]\u0006 רק דבר ש\u0003ראוי\u0004 לבוא לידי האב שמת\u0003, ו\u0004כלל הוא ש\u0003אין הבכור נוטל\u0004 פי שנים \u0003בראוי כבמוחזק.\u0004","\u0003אמר רב כהנא, כללא דשושבינותא\u0004 \u0005[הכלל של השושבינות],\u0006 כלומר, באלו אופנים מתקיימת חובת ההחזרה של דמי השושבינות: אם \u0003הוה במתא\u0004 \u0005[היה בעיר]\u0006 כשנישא שושבינו — \u0003איבעי ליה למיתא\u0004 \u0005[צריך היה לו לבוא\u0006 לחתונה\u0005],\u0006 וגם אם לא בא — צריך לתת לו את השושבינות. וכן אם לא היה בעיר, אבל \u0003שמע קל טבלא\u0004 \u0005[קול התוף\u0006 המודיע שיש חתונה\u0005]\u0006 — \u0003איבעי ליה למיתא\u0004 \u0005[צריך היה לו לבוא].\u0006 \u0003לא שמע\u0004 את \u0003קל טבלא\u0004 \u0005[קול התוף]\u0006 — \u0003איבעי ליה לאודועיה\u0004 \u0005[צריך היה\u0006 \u0005לו\u0006 החתן \u0005להודיע לו],\u0006 אלא שאף ש\u0003תרעומת אית ליה\u0004 \u0005[יש לו]\u0006 לשושבין שלא הודיע לו ולא הזמינו להשתתף בשמחה, \u0003שלומי\u0004 \u0005[לשלם]\u0006 הוא \u0003משלם.\u0004 ומכל מקום הואיל ולא נהנה השושבין מן החתונה, מן הראוי שינכה לו מן השושבינות.","ושואלים: \u0003ועד כמה\u0004 ינכה לו? \u0003אמר אביי: נהגו בני גננא\u0004 \u0005[החופה],\u0006 אם היה חוב השושבינות \u0003עד זוזא\u0004 \u0005[זוז]\u0006 אינו משלם כלל, כי \u0003אייתא בכפיה אכליה בכרסיה\u0004 \u0005[\u0006מה ש\u0005הביא\u0006 אדם \u0005בידו אכל בכרסו].\u0006 אם השושבינות היא \u0003עד ארבעה\u0004 זוזים — \u0003משלם פלגא\u0004 \u0005[מחצית].\u0006 \u0003מכאן ואילך\u0004 אם חייב לו סכום גדול יותר — \u0003איניש איניש כחשיבותיה\u0004 \u0005[איש איש כחשיבותו].\u0006 שלפי האופן שבו היו מכבדים אותו ומאכילים אותו — כך הוא מנכה.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עשה עמו\u0004 עם חבירו שושבינות \u0003בפומבי\u0004 (בפרסום), \u0003ובקש\u0004 הוא מחבירו \u0003לעשות עמו\u0004 חתונה \u0003בצנעא\u0004 — \u0003יכול לומר לו\u0004 השושבין: באופן זה אינו רוצה להשתתף עמך, אלא \u0003בפומבי אעשה עמך, כדרך שעשית עמי.\u0004 וכן אם \u0003עשה עמו בבתולה,\u0004 שנשא חבירו בתולה לאשה, \u0003ובקש\u0004 הוא מחבירו \u0003לעשות\u0004 \u0003עמו\u0004 שושבינות בנישואיו ל\u0003אלמנה\u0004 — \u0003יכול\u0004 חבירו \u0003לומר לו:\u0004 דווקא \u0003בבתולה אעשה עמך, כדרך שעשית עמי,\u0004 שמחה גדולה יותר\u0003;\u0004 וכן אם","\u0003עשה עמו,\u0004 עם חבירו, שושבינות \u0003ב\u0004אשה \u0003שניה\u0004 שנושא, שהיא שמחה שונה משמחת נישואי אשה ראשונה, \u0003ובקש\u0004 מחבירו \u0003לעשות עמו\u0004 בנישואין של \u0003ראשונה\u0004 — \u0003יכול לומר לו\u0004 חבירו: \u0003לכשתשא אשה אחרת אעשה עמך. עשה עמו\u0004 בנישואי אשה \u0003אחת, ובקש\u0004 מחבירו \u0003לעשות עמו בשתים\u0004 — \u0003יכול לומר לו: באחת אעשה עמך, כדרך שעשית עמי.\u0004","אגב הזכרת \"פומבי\" מביאים דברים בהם נזכרת מלה זו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עתיר נכסין עתיר פומבי\u0004 \u0005[עשיר בנכסים\u0006 ו\u0005עשיר בפרסום]\u0006 — \u0003זה הוא בעל הגדות. עתיר סלעים עתיר תקוע\u0004 \u0005[עשיר\u0006 \u0005כספים\u0006 ו\u0005עשיר בבתים],\u0006 שהוא כאדם שיש לו כסף מזומן — \u0003זהו בעל פלפול. עתיר משח עתיר כמס\u0004 \u0005[עשיר בשמן\u0006 ו\u0005עשיר בדברים\u0006 \u0005נסתרים]\u0006 — \u0003זהו בעל שמועות\u0004 שיודע הרבה שמועות והלכות של האמוראים. \u0003הכל צריכין למרי חטיא\u0004 \u0005[לבעל החיטים]\u0006 — \u0003תלמוד,\u0004 שמי שמבין ועוסק בטעמי ההלכות והשמועות, כולם צריכים לו.","\u0003אמר ר' זירא אמר רב, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כל ימי עני רעים\u0004 וטוב לב משתה תמיד\u0003\"\u0004 (משלי טו, טו)? \"כל ימי עני רעים\" — \u0003זה בעל תלמוד\u0004 שמתייגע בלימודו ובקושיותיו, \u0003\"וטוב לב משתה תמיד\"\u0004 — \u0003זה בעל משנה\u0004 ששונה משנתו כסדרה, ואינו מתייגע בה כל כך.","\u0003רבא אמר: איפכא\u0004 \u0005[ההיפך]\u0006 הוא הנכון. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רב משרשיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מסיע אבנים יעצב בהם בוקע עצים יסכן בם\"\u0004 (קהלת י, ט)? \u0003\"מסיע אבנים יעצב בהן\"\u0004 — \u0003אלו בעלי משנה,\u0004 שהם עובדים קשה בשינונם, אבל אינם יכולים להינות מעמלם — להגיע למסקנות למעשה מתוך משנתם. \u0003\"בוקע עצים יסכן\u0004 (יתחמם) \u0003בם\"\u0004 — \u0003אלו בעלי תלמוד,\u0004 שאחרי שיגעו בלימוד הם מגיעים למסקנות.","\u0003ר' חנינא אמר\u0004 פירוש אחר לפסוק שהובא \u0003: \"כל ימי עני רעים\"\u0004 — \u0003זה שיש לו אשה רעה, \"וטוב לב משתה תמיד\"\u0004 — \u0003זה שיש לו אשה טובה. ר' ינאי אמר: \"כל ימי עני רעים\"\u0004 — \u0003זה איסטניס,\u0004 אדם מפונק, רגיש, לפי שתמיד הוא מוצא דברים שאינם נעימים לו. \u0003\"וטוב לב משתה תמיד\"\u0004 — \u0003זה שדעתו יפה\u0004 שאינו מקפיד כל כך, וסובל דברים ואינו נפגע.","\u0003ר' יוחנן אמר\u0004 פירוש אחר לפסוק זה \u0003: \"כל ימי עני רעים\"\u0004 — \u0003זה רחמן,\u0004 שהרי יש בעולם הרבה מקרים של צער וסבל, \u0003\"וטוב לב משתה תמיד\"\u0004 — \u0003זה אכזרי,\u0004 שאינו סובל ביסורי אחרים. \u0003ור' יהושע בן לוי אמר\u0004 פירוש אחר \u0003: \"כל ימי עני רעים\"\u0004 — \u0003זה שדעתו קצרה\u0004 רגזן המתרתח במהרה, \u0003\"וטוב לב משתה תמיד\"\u0004 — \u0003זה שדעתו רחבה,\u0004 סבלן."]]};
